كـ ُـم بصـ ِ‬\n        ‫ـرف ال َّنظـ ِـر عـ ِـن َّ‬                  ‫الشــرعيةِ‪َّ ،‬‬    ‫ـام املرافعـ ِ‬\n                                                                 ‫ـات َّ‬             ‫مِ ــن ِنظـ ِ‬\n‫ـاص‪ ،‬وصـ ّـد َق احلكـ ُـم مـ َـن الدائــر ِة احلقوقي ـ ِة السادس ـ ِة‬   ‫ـدم االخ ِتصـ ِ‬ ‫لعـ ِ‬\n                                                 ‫ـتئناف ِبنطق ـ ِة َم َّ‬\n                                ‫ك ـ َة املكرم ـةِ‪.‬‬                  ‫ِ‬    ‫مبحكم ـ ِة االسـ‬\n\n\n\n\n‫ـدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬      ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n‫ـاء علــى املعاملــة احملالــة إلينــا مــن قِ بــل فضيلــة‬\n                                                         ‫مبكــة املكرمــة‪ ،‬وبنـ ً‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ .........‬وتاريــخ‬\n‫‪1434/01/19‬هـ املقيدة باحملكمة برقم ‪ .........‬وتاريخ ‪1434/01/19‬‬\n‫هــ‪ ..‬فإنــه يف يــوم الســبت املوافــق ‪1434/03/28‬ه ـ افتتحــت اجللســة يف‬\n‫صباحــا للنظــر يف ‪ ...‬ضــد ‪ ...‬بشــأن‬\n                                    ‫ً‬       ‫متــام الســاعة احلاديــة عشــرة والنصــف‬\n                          ‫طلبــه املــدون بصحيفــة دعــواه لفــة (‪ )2‬املتضمــن‪:‬‬\n‫(أطلــب مــا يلــي‪ :‬إحضــار املذكــورة أعــاه وأطلــب تســليمي جــواز‬\n‫الســفر)‪ ،‬ومبــا أن طلــب املدعــي هــو اســترداد حيــازة متعلــق مبنقــول‬\n‫فقــد جــرى منــي بعثهــا بالكتــاب رقــم ‪ 34155967‬يف ‪1434/02/11‬ه ـ‬\n‫للمحكمــة اجلزئيــة مبكــة املكرمــة كونهــا جهــة االختصــاص حســب‬\n‫مــا اقتضــاه نظــام املرافعــات الشــرعية والئحته التنفيذيــة‪ ،‬مبوجب املادة‬\n‫احلاديــة والثالثــن منــه املتضمنــة أنــه‪( :‬مــن غيــر إخــال مبــا يقضــي بــه‬\n‫نظــام ديــوان املظالــم‪ ،‬ومبــا للمحاكــم العامــة مــن اختصــاص يف نظــر‬\n‫الدعــوى العقاريــة ـ ـ تختــص احملاكــم اجلزئيــة باحلكــم يف الدعــاوى‬\n‫اآلتيــة ا‪ /‬دعــوى منــع التعــرض للحيــازة ودعــوى اســتردادها)‪ ..‬فأعادهــا‬\n‫فضيلــة رئيــس احملكمــة اجلزئيــة مبكــة املكرمــة مبوجــب كتابــه‬\n‫رقــم ‪ .........‬يف ‪1434/03/15‬ه ـ واملتضمــن إشــارة فضيلــة القاضــي‪/‬‬\n\n                                                                                                    ‫‪60‬‬\n\f     ‫‪« :...‬بــأن املــادة املشــار إليهــا مــن نظــام املرافعــات الشــرعية يف الفقــرة‬\n     ‫الرابعــة نصــت علــى اآلتــي‪( :‬دعــوى اســترداد احليــازة هــي‪ :‬طلــب مــن‬\n     ‫كانــت العــن بيــده‪ ،‬و ُأخــذت منــه بغيــر حــق كغصــب وحيلــة‪ ،‬إعــادة‬\n     ‫حيازتهــا إليــه حتــى صــدور حكــم يف املوضوع بشــأن املســتحق لها)‪ ،‬وال‬\n     ‫يوجــد بصحيفــة الدعــوى أو إقــرار املدعــي مــا يفيــد بــأن األوراق ُأخــذت‬\n     ‫بغيــر حــق‪ .‬وعليــه‪ ،‬فــا تكــون هــذه الدعــوى مــن اختصــاص احملكمــة‬\n     ‫اجلزئيــة»‪ ،‬وحيــث إن ذكــر الغصــب واحليلــة كمــا يف الفقــرة الرابعــة‬\n     ‫مــن الالئحــة التنفيذيــة للمــادة احلاديــة والثالثــن مــن نظــام املرافعــات‬\n     ‫الشــرعية املتضمنــة‪( :‬دعــوى اســترداد احليــازة هــي طلــب مــن كانــت‬\n     ‫العــن بيــده و ُأخــذت منــه بغيــر حــق كغصــب وحيلــه إعــادة حيازتهــا لــه‬\n     ‫حتــى صــدور حكــم يف املوضــوع بشــأن املســتحق لهــا) ـ ـ هــو للتشــبيه ال‬\n     ‫للحصــر‪ ،‬فحــرف الــكاف يف لغــة العــرب ال يــرد يف اســتعمال احلصــر‪،‬‬\n     ‫(يشــترط‬   ‫كمــا أن الفقــرة اخلامســة مــن الالئحــة التنفيذيــة تضمنــت ُ‬\n     ‫لســماع دعــوى اســترداد احليــازة ثبــوت حيــازة العــن مــن املدعــي قبــل قيام‬\n     ‫ســبب الدعــوى ولــو بغيــر امللــك)‪ ..‬ونصــت الفقــرة السادســة مــن الالئحــة‬\n     ‫أيضــا علــى «دعــوى منــع التعــرض للحيــازة ودعــوى اســتردادها‬  ‫التنفيذيــة ً‬\n     ‫املتعلقــة باملنقــول إذا رفعــت بــه دعــوى مســتقلة قبــل رفع الدعــوى األصلية‬\n     ‫يف املوضــوع تختــص بنظرهــا احملكمــة اجلزئيــة وفــق املــادة (‪ ،»)31‬ولــو‬\n     ‫ســلمنا لفضيلته بأن التســليم كان بوجه حق فإنها حينئذٍ تصبح دعوى‬\n     ‫موضوعيــة تختــص بهــا احملكمــة املختصــة‪ ،‬ومعلــوم أن طلــب املدعــي ال‬\n     ‫ميكــن تقديــره حســب االختصــاص القيمــي للمحاكــم لكــون احملــاز‬\n     ‫ال ميكــن تقديــره‪ ،‬فعــاد إلــى األصــل وهــو اختصــاص احملاكــم اجلزئيــة‬\n     ‫بدعــاوى اســترداد وحيــازة املنقــول‪ ..‬قيــل يف (الكاشــف يف شــرح نظــام‬\n\n\n‫‪61‬‬\n\f‫املرافعــات الشــرعية)‪« :‬فــإن ســلمها احلائــز باختيــاره للمدعــى عليــه مــن‬\n‫غيــر حيلــة اختصــت بنظرهــا احملكمــة املختصــة باملوضــوع كدعــوى‬\n‫موضوعيــة؛ ألنهــا حينئــذ تكــون مــن الدعــاوى املوضوعيــة» [ الكاشــف‬\n‫‪ ، ]167/1‬كمــا أنــه لــو ســلمنا بــرأي فضيلتــه فــإن حيــازة املدعــى عليهــا‬\n‫جلــواز ســفر املدعــي لــو ثبتــت فإنهــا حيــازة بغيــر حــق يف كل األحــوال؛ إذ‬\n‫نصــت املــادة العشــرون مــن الالئحــة التنفيذيــة لنظــام وثائــق الســفر علــى‬\n‫أن‪« :‬جواز الســفر وثيقة رســمية ملن صدر باســمه‪ ،‬ويلزم احملافظة عليه‬\n‫وعــدم تســليمه للغيــر»‪ ،‬كمــا أنــه صــدر عــدد مــن الســوابق القضائيــة‬\n‫واملؤيــدة مــن مرجعهــا باختصــاص احملاكــم اجلزئيــة بدعــاوى اســترداد‬\n‫حيــازة املنقــول يف مثــل القضيــة محــل الدعــوى؛ كالقــرار الصــادر عــن‬\n‫هــذه احملكمــة برقــم ‪ .........‬يف ‪1433/12/22‬ه ـ واملؤيــد بقــرار الدائــرة‬\n‫احلقوقيــة الرابعــة مبحكمــة االســتئناف مبكــة املكرمــة رقــم ‪ .........‬يف‬\n‫‪1434/01/07‬هــ‪ ،‬وحيــث إن مثــل هــذا القرار آنف الذكر الصادر عن‬\n‫محكمــة مختصــة فاصلــة يف التنــازع حــول االختصــاص النوعــي محــدد‬\n‫لالختصــاص يف الدعــاوى مثيالتهــا‪ .‬وعليــه‪ ،‬وحيــث إن جميــع مــا ســبق‬\n‫يــدل داللــة واضحــة علــى اختصــاص احملكمــة اجلزئيــة بنظــر الدعــوى‪،‬‬\n‫واســتنا ًدا إلــى املــادة الرابعــة والســبعني مــن النظــام املذكــور بعاليــه‪،‬‬\n‫ولتحقــق التدافــع الــوارد فيهــا فقــد صــرف النظــر عــن هــذه الدعــوى‬\n‫ـرت بإصــدار قــرار بذلــك ورفعــه‬   ‫لعــدم االختصــاص‪ ،‬وبــه قضيـ ُـت وأمـ ُ‬\n‫حملكمــة االســتئناف للفصــل يف ذلــك‪ ..‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف ‪1434/03/28‬هــ‪.‬‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل‪ ،‬وبعــد‪ ..‬فق ــد ج ــرى‬\n‫م ّنــا نح ــن رئيــس وأعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n\n\n                                                                                     ‫‪62‬‬\n\f     ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطِّ ــا ُع عل ــى القــرار الشــرعي‬\n     ‫الصــادر عــن فضيلــة الشــيخ‪ ... /‬القاضــي باحملكمــة العامــة مبكــة‬\n     ‫املكرمــة برقــم ‪ .........‬وتاريــخ ‪1434/3/28‬هــ‪ ،‬املتضمــن دعــوى ‪ ...‬ضــد‬\n     ‫‪ ...‬احملكــوم في ــه مبــا دون باطنــه‪ ..‬وبدراس ــة احلكــم وص ــورة ضبط ــه‪،‬‬\n     ‫تق ــررت املوافق ــة عليــه‪ .‬واهلل املوفــق‪ ،‬وصل ــى اهلل عل ــى نبينــا محمــد‬\n                                                        ‫وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪63‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":52,"source_page_end":63,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f96a2749ec24f7f518136f428fd3a7f1e32ca5516d593f7f1c44f17f31d3d26b","normalized_text_hash":"2534920608bb336636654acf5f0ae9f9118ba160f1d22f5db649f39851a3a014","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p52-3428954"},{"id":"043c26d0-874d-54a2-ad98-aa6c7f8300ae","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -مطالبة بصرف مستحقات إيجار محل كهرباء -سبق احلكم يف ذات الدعوى -املختص بنظر الدعوى مصدر احلكم أو خلفه (تكييف الدعوى) -مطالبة ببيع احملل باملزاد العلني وتقاضي اإليجارات السابقة -صرف النظر لعدم االختصاص .","document_number":"3436726","case_number":"33503972","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/13","year":"1434","subject":"اختصاص -مطالبة بصرف مستحقات إيجار محل كهرباء -سبق احلكم يف ذات الدعوى -املختص بنظر الدعوى مصدر احلكم أو خلفه (تكييف الدعوى) -مطالبة ببيع احملل باملزاد العلني وتقاضي اإليجارات السابقة -صرف النظر لعدم االختصاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3436726 :‬تاريخه‪1434/2/13:‬هـ‬\n                 ‫رقم الدعوى‪33503972 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3436726‬تاريخه‪1434/2/13:‬هـ‬\n\n\n‫اختصــاص ‪ -‬مطالبــة بصــرف مســتحقات إيجــار محــل كهربــاء‪ -‬ســبق‬\n‫احلكــم يف ذات الدعــوى‪ -‬املختــص بنظــر الدعــوى مصــدر احلكــم أو‬\n‫خلفــه (تكييــف الدعــوى)‪ -‬مطالبــة ببيــع احملــل باملــزاد العلنــي وتقاضي‬\n               ‫اإليجــارات الســابقة‪ -‬صــرف النظــر لعــدم االختصــاص ‪.‬‬\n\n\n\n\n       ‫‪ .1‬املادة ‪ 7/11‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n       ‫‪ .2‬املادة ‪ 2/71‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n       ‫‪ .3‬املادة ‪ 2/74‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n‫قــدم أحــد الورثــة الئحــة دعــوى يدعــي فيهــا باملطالبة بصرف مســتحقات‬\n‫محــل كهربــاء ‪ ،‬وباطــاع ناظــر القضيــة علــى املعاملــة تبــن وجــود صورة‬\n‫صــك صــادر مــن أحــد قضــاة احملكمــة بــن طــريف الدعــوى ويتضمــن‬\n‫إثبــات محــل الكهربــاء ملورثهمــا ‪ ،‬ومبــا أن هــذه الدعــوى ناشــئة عــن‬\n‫احلكــم الســابق ‪ ،‬ومبــا أن فضيلــة مصــدر احلكــم علــى رأس العمــل يف‬\n‫احملكمــة نفســها وبنــاء علــى املــادة ‪ 7/11‬جــرى بعــث املعاملــة حلاكــم‬\n‫القضيــة ‪ ،‬لكــن عــادت املعاملــة منــه بعــدم وجــود عالقــة لهــذه الدعــوى‬\n‫بالدعــوى التــي كانــت لديــه ‪ ،‬ومبــا أن املدعــي يدعــي أن املــال الــذي‬\n\n                                                                                 ‫‪64‬‬\n\f     ‫يطلبــه مــن املدعــى عليــه هــو مــن احملــل الــذي أثبتــه مصــدر احلكــم‬\n     ‫الســابق أنــه ملــورث املدعــى عليهــم وملكيتــه كان مــن قبلــه ‪ ،‬كمــا‬\n     ‫أن املدعــي يطلــب بيعــه باملــزاد العلنــي مــع أخــذ اإليجــارات ‪ ،‬وهــذا‬\n     ‫ناشــئ مــن احلكــم الســابق ‪ ،‬وبنــاء علــى املــادة ‪ 2/71‬واملــادة ‪2/74‬‬\n     ‫واملــادة‪ 7/11‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة مت‬\n     ‫احلكــم بصــرف النظــر لعــدم االختصــاص وأن املختــص بنظرهــا هــو‬\n     ‫فضيلــة مصــدر احلكــم الســابق وجــرى إعــام املدعــي باحلكــم وصــدق‬\n     ‫احلكــم مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة‬\n                                                               ‫مكــة املكرمــة ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.........‬القاضــي يف احملكمــة‬\n     ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪.........‬‬\n     ‫وتاريــخ ‪1433/08/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ .........‬وتاريــخ‬\n     ‫‪1433/08/04‬ه ـ ففــي يــوم اإلثنني‪1433/12/20‬ه ـ افتتحــت اجللســة يف‬\n     ‫الســاعة الثامنــة والربــع وباالطــاع علــى املعاملــة وجــد بهــا علــى لفــة رقــم‬\n     ‫‪ )1( :‬صــورة الصــك رقــم ‪ .........‬وتاريــخ ‪1433/05/23‬ه ـ الصــادر مــن‬\n     ‫فضيلــة الشــيخ ‪ .........‬القاضــي بهــذه احملكمــة بدعــوى بــن الطرفــن‬\n     ‫نفســيهما ويتضمــن إثبــات أن محــل الكهربــاء املذكــور يف الدعــوى هــو‬\n     ‫ملورثهمــا ومبــا أن هــذه الدعــوى تتضمــن املطالبــة مــن املدعــي للمدعــى‬\n     ‫عليهــا بصــرف املســتحقات خــال فتــرة ماضيــة كمــا يظهــر مــن‬\n     ‫صحيفــة الدعــوى املرفــق باملعاملــة كمــا علــى لفــة رقــم ‪ ،) 3 ( :‬وعليــه‬\n     ‫فهــذه الدعــوى ناشــئة مــن ذلــك احلكــم‪ ،‬وعليــه فهــي مــن اختصــاص‬\n\n‫‪65‬‬\n\f‫فضيلــة الشــيخ ‪.........‬؛ وفقــا للمــادة ‪ 7/11‬والتــي تنــص ‪ ( :‬كل دعــوى‬\n‫نشــأت عــن حكــم يف قضيــة ســابقة فينظرهــا مصــدر احلكــم الســابق‬\n‫إذا كان علــى رأس العمــل يف احملكمــة نفســها وكانــت مشــمولة‬\n‫بواليتــه )‪ ،‬وفضيلــة الشــيخ ‪.........‬مــا زال بهــذه احملكمــة وعليــه فقــد‬\n‫قــررت بعــث املعاملــة لفضيلتــه‪ ،‬واختتمــت اجللســة ثــم يف يــوم الثالثــاء‬\n‫‪1434/02/12‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة والربــع وفيهــا‬\n‫حضــر املدعــي أصالة‪.........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.........‬لســماع دعــواه علــى ‪ .........‬بشــأن دعــوى قســمة تركــة‬\n‫إجبــار ‪ /‬عقاريــة وعليــه مت بعــث املعاملــة لفضيلتــه باخلطــاب رقــم ‪.........‬‬\n‫وتاريــخ ‪1433/12/20‬ه ـ ملــا ذكــر ســابقا واملتضمــن‪ (:‬وباالطــاع‬\n‫علــى املعاملــة وجــد بهــا علــى لفــة رقــم‪ )1( :‬صــورة الصــك رقــم ‪.........‬‬\n‫وتاريــخ ‪1433/05/23‬ه ـ الصــادرة مــن فضيلــة الشــيخ ‪.........‬القاضــي‬\n‫بهــذه احملكمــة واملتعلــق بدعــوى بــن الطرفــن نفســيهما ويتضمــن‬\n‫إثبــات أن محــل الكهربــاء املذكــور يف الدعــوى هــو ملورثهمــا‪ ،‬ومبــا‬\n‫أن هــذه الدعــوى تتضمــن املطالبــة مــن املدعــي للمدعــى عليهمــا بصــرف‬\n‫املســتحقات خــال فتــرة ماضيــة كمــا يظهــر يف صحيفــة الدعــوى كما‬\n‫علــى لفــة رقــم‪ ،)3(:‬وعليــه فهــذه دعــوى ناشــئة مــن ذلــك احلكــم‪ ،‬وعليــه‬\n‫فهــي مــن اختصــاص فضيلــة الشــيخ ‪.........‬؛ وفقــا للمــادة ‪ 7/11‬والتــي‬\n‫تنــص‪ (:‬كل دعــوى نشــأت عــن حكــم يف قضيــة ســابقة فينظرهــا‬\n‫مصــدر احلكــم الســابق إذا كان علــى رأس العمــل يف احملكمــة‬\n‫نفســها وكانــت مشــمولة بوالية)‪،‬وفضيلــة الشــيخ ‪.........‬مــازال بهــذه‬\n‫احملكمــة‪ ،‬آمــل بعــث املعاملــة لفضيلتــه) ا‪.‬ه ـ ومــن ثــم عــادت املعاملــة‬\n‫باخلطــاب رقــم ‪ .........‬وتاريــخ ‪1434/02/02‬ه ـ مــن فضيلــة الشــيخ ‪.........‬‬\n\n\n                                                                                     ‫‪66‬‬\n\f     ‫واملتضمــن‪ (:‬عــدم وجــود عالقــة لهــذه الدعــوى بالدعــوى التــي لدينــا)‬\n     ‫أ‪.‬ه ـ وباالطــاع علــى صحيفــة الدعــوى وجــد أنهــا تتضمــن مــا يلي(أقــدم‬\n     ‫دعــواي ضــد املدعــى عليهــا املوضــح اســمها بعاليــه وموضــوع الدعــوى‬\n     ‫بالتفصيــل مــا يلــي‪ :‬اســتخراج مســتحقاتي مــن املبالــغ التــي صرفــت‬\n     ‫خــال الفتــرة والبالــغ (‪)104000‬مائــة وأربعــة أالف ريــال والتــي كانــت‬\n     ‫تســلم لهــا إضافــة إلــى عــرض محــل الكهربــاء يف املــزاد العلنــي وصــرف‬\n     ‫حقوقــي ومســتنداتي مــا يلــي‪ :‬صــك شــرعي الصــادر مــن احملكمــة‬\n     ‫العامــة مبحافظــة جــدة برقــم ‪ .........‬وتاريــخ ‪1433/05/23‬ه ـ وأطلــب‬\n     ‫مــا يلــي‪ :‬محاســبتها عــن املبالــغ التــي كانــت تســتلمها واســتخراج حقــي‬\n     ‫الشــرعي التــي تســتفيد منــه طــوال الفتــرة ومنــذ وفــاة زوجهــا وعــرض‬\n     ‫احملــل للبيــع يف املــزاد العلني)ا‪.‬ه ـ نقــل نصــا وعليــه فــا يظهر لــي أن هذه‬\n     ‫الدعــوى داخلــة يف واليتــي وقــد قــرر أهــل العلــم أن مــن ال واليــة لــه فــا‬\n     ‫ينفــذ حكمــه فاملدعــي يدعــي أن املــال الــذي يطلبــه مــن املدعــى عليهــا‬\n     ‫هــو مــن احملــل الــذي أثبتــه فضيلتــه أنــه ملــورث املدعــى عليهــم وملكيتــه‬\n     ‫كان مــن قبلــه كمــا أن املدعــي يطلــب بيعــه يف املــزاد العلنــي مــع أخــذ‬\n     ‫اإلجــارات وهــذا كلــه نشــأ مــن حكــم فضيلــة الشــيخ ‪.........‬وعليــه‬\n     ‫فالنظــر لفضيلتــه وبعــد االطــاع علــى املــادة (‪)71‬احلاديــة والســبعني مــن‬\n     ‫نظــام املرافعــات الشــرعية ونصهــا ‪ (:‬الدفــع ببطــان صحيفــة الدعــوى‬\n     ‫أو بعــدم االختصــاص احمللــي أو بإحالــة الدعــوى إلــى محكمــة أخــرى‬\n     ‫لقيــام النــزاع ذاتــه أمامهــا أو لقيــام دعــوى أخــرى مرتبطــة بهــا يجــب‬\n     ‫إبــداؤه قبــل أي طلــب أو دفــاع يف الدعــوى وإال ســقط احلــق فيمــا لــم يبــد‬\n     ‫منهــا ) كمــا جــاء يف الفقــرة الثانيــة مــن الالئحــة التنفيذيــة ‪...‬لــه تابــع‬\n     ‫لهــذه املــادة ونصهــا ‪(:‬اإلرتبــاط يف هــذه املــادة هــو‪ :‬اتصــال الدعــوى‬\n\n\n‫‪67‬‬\n\f‫الالحقــة بالســابقة يف املوضــوع أو الســبب وال يلــزم احتادهمــا يف‬\n‫املقــدار) وبعــد االطــاع علــى املــادة (‪)74‬الرابعــة والســبعني مــن نظــام‬\n‫املرافعــات الشــرعية ونصهــا ‪ (:‬يجــب علــى احملكمــة إذا حكمــت بعــدم‬\n‫اختصاصهــا أن حتيــل الدعــوى إلــى احملكمــة املختصــة وتعلــم اخلصــوم‬\n‫بذلــك) والفقــرة الثانيــة مــن الالئحــة التنفيذيــة للمــادة نفســها ونصهــا‪(:‬‬\n‫إذا حتقــق التدافــع يف نظــر الدعــوى فعلى التفصيل التالي‪:‬ـ (أ) إذا كان‬\n‫التدافــع بــن قضــاة احملكمــة الواحــدة أو بــن رئيــس احملكمــة وأحــد‬\n‫قضاتهــا أو بــن محكمتــن تابعتــن جلهــة قضائيــة واحــدة فعلــى مــن‬\n‫أحيلــت إليــه أوال ثــم أعيــدت إليــه ثانيــا ولــم يقتنــع باختصاصــه بهــا أن‬\n‫يصــدر قــرارا بصــرف النظــر بعــدم اختصاصــه‪ ،‬وعليــه أن يرافــع القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة إلــى محكمــة التمييــز للفصــل يف‬\n‫ذلــك‪ ،‬ومــا تقــرره يلــزم العمــل بــه ويعلــم القاضــي اخلصــوم بذلــك) وعليــه‬\n‫وحلصــول التدافــع فقــد قــررت صــرف النظــر عــن هــذه الدعــوى لعــدم‬\n‫االختصــاص وأن املختــص بهــا فضيلــة الشــيخ ‪.........‬وبــه حكمــت وقــد‬\n‫أعلمــت املدعــي بذلــك وقــررت إصــدار قــرار بذلــك ورفعــه مــع صــورة‬\n‫الضبــط وكامــل املعاملــة حملكمــة االســتئناف‪ ،‬واختتمــت اجللســة يف‬\n‫الســاعة التاســعة والنصــف‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n             ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/02/12‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جــده املســاعد برقــم ‪ .........‬وتاريــخ‬\n‫‪1434/2/19‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪.........‬‬\n\n\n                                                                                     ‫‪68‬‬\n\f     ‫القاضــي باحملكمــة العامــة مبحافظــة جــده برقــم ‪ .........‬وتاريــخ‬\n     ‫‪1434/2/13‬ه ـ ‪ ،‬املتضمــن دعوى‪.........‬ضــد ‪ ،.........‬وبدراســة القــرار‬\n     ‫وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكــم بصــرف النظــر‬\n     ‫لعــدم االختصــاص ‪ .‬واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                                      ‫وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪69‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":64,"source_page_end":69,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d1cc17d2d4d23a96e5842d8d29852257dc5e47b8a91ec9432547d7bc528ce5e7","normalized_text_hash":"e3525999ff244743bd75055c07e336bf21c7faccb45d86add7e484c322dd20a9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p64-3436726"},{"id":"24fa36ca-38bb-507e-b12a-ae6950666bf7","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -قسمة تركة -وفاة مورث ترك عقار ا جتاري ا وآخر سكني ا -قيام بعض الورثة باالستيالء ووضع اليد على العقارين وأخذ ريعهما -مطالبة املدعي بأخذ نصيبه من ريع العقارين- وجود دعوى منظورة بخصوص قسمة العقار محل الدعوى -عدم جواز نظر أكثر من دعوى يف قسمة تركة واحدة يف آن واحد- حتقق التدافع -صرف النظر عن الدعوى لعدم االختصاص .","document_number":"3453923","case_number":"33179841","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/2","year":"1434","subject":"اختصاص -قسمة تركة -وفاة مورث ترك عقار ا جتاري ا وآخر سكني ا -قيام بعض الورثة باالستيالء ووضع اليد على العقارين وأخذ ريعهما -مطالبة املدعي بأخذ نصيبه من ريع العقارين- وجود دعوى منظورة بخصوص قسمة العقار محل الدعوى -عدم جواز نظر أكثر من دعوى يف قسمة تركة واحدة يف آن واحد- حتقق التدافع -صرف النظر عن الدعوى لعدم االختصاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3453923 :‬تاريخه‪1434/3/2 :‬هـ‬\n                   ‫رقم الدعوى‪33179841 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34216888‬تاريخه‪1434/5/20 :‬هـ‬\n\n\n‫اختصــاص ‪ -‬قســمة تركــة‪ -‬وفــاة مــورث تــرك عقــار ًا جتاري ـ ًا وآخــر‬\n‫ســكني ًا‪ -‬قيــام بعــض الورثــة باالســتيالء ووضــع اليــد علــى العقاريــن‬\n‫وأخــذ ريعهمــا‪ -‬مطالبــة املدعــي بأخــذ نصيبــه مــن ريــع العقاريــن‪-‬‬\n‫وجــود دعــوى منظــورة بخصــوص قســمة العقــار محــل الدعــوى‪ -‬عــدم‬\n‫جــواز نظــر أكثــر مــن دعــوى يف قســمة تركــة واحــدة يف آن واحــد‪-‬‬\n   ‫حتقــق التدافــع‪ -‬صــرف النظــر عــن الدعــوى لعــدم االختصــاص ‪.‬‬\n\n\n\n\n       ‫‪ .1‬املادة ‪ 6/11‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n          ‫‪ .2‬املادة ‪ 74‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n‫ادعــى املدعــي أصالــة ووكالــة ضــد املدعــى عليهمــا بــأن مورثــه‬\n‫ومورثهــم‪ ،‬خ ّلــف مــن ضمــن تركتــه عقــار ًا جتاري ـ ًا مكون ـ ًا مــن شــقق‬\n‫ســكنية ومحــات جتاريــة‪ ،‬وكذلــك عقــار ًا آخــر ســكني ًا مكونـ ًا مــن‬\n‫ســت شــقق ســكنية‪ ،‬وقــد قــام املدعــى عليــه احلاضــر باالســتيالء ووضع‬\n‫اليــد علــى العقــار األول مــن تاريــخ ‪1425/3/15‬ه ـ وأخــذ ريعهــا وســكن‬\n‫فيهــا بــدون أن يســلم للورثــة أجــرة الشــقتني اللتــن ســكن فيهمــا‪،‬‬\n‫كمــا قــام املدعــى عليــه الثانــي الغائــب باالســتيالء ووضــع اليــد علــى‬\n\n                                                                                  ‫‪70‬‬\n\f     ‫العقــار الثانــي وأخــذ ريعــه مــن حــن وفــاة مورثهــم حتــى حينــه ويطلــب‬\n     ‫إلــزام املدعــى عليهمــا بتســليمه وموكليــه نصيبهــم مــن إرث مورثهــم‬\n     ‫مــن ريــع هذيــن العقاريــن مــن حــن اســتالم كل واحــد منهمــا للعقــار‬\n     ‫‪ ،‬وأمــا قســمة العقــار فلديهــم دعــوى منظــورة لــدى املكتــب القضائــي‬\n     ‫الثالــث باحملكمــة العامــة بنجــران ولــم يصــدر فيهــا أي حكــم حتــى‬\n     ‫حينــه هكــذا ادعــى ‪ -‬أجــاب املدعــى عليــه األول باملصادقــة علــى دعــوى‬\n     ‫املدعــي وأن ســكنه برضــا كل الورثــة هكــذا أجــاب ‪ ،‬وبنــاء علــى‬\n     ‫أن هــذه الدعــوى وهــي دعــوى يف ريــع عقــار وهــو جــزء مــن التركــة‪،‬‬\n     ‫ومبــا أن دعــوى التركــة ال تــزال منظــورة لــدى قــاض آخــر‪ ،‬ومبــا أن‬\n     ‫معاملــة قســمة التركــة أحليــت إلــى فضيلتــه أوالً‪ ،‬لذلــك كلــه فهــذه‬\n     ‫القضيــة هــي مــن اختصاصــه‪ ،‬وجــرى بعــث املعاملــة لــه‪ ،‬حســب املــادة‬\n     ‫(‪ )6/11‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة‪ ،‬ثــم عــادت‬\n     ‫مــن فضيلتــه‪ ،‬وحيــث حتقــق التدافــع املنصــوص عليــه يف املــادة الرابعــة‬\n     ‫والســبعني مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة‪ -‬وملــا‬\n     ‫تقــدم كلــه صــدر احلكــم بصــرف النظــر عــن هــذه الدعــوى لعــدم‬\n     ‫االختصــاص‪ ،‬وبعــث املعاملــة إلــى محكمــة االســتئناف للفصــل يف‬\n     ‫ذلــك‪ ،‬وجــرى إعــام الطرفــن بذلــك ‪ ،‬وصــدق احلكــم مــن الدائــرة‬\n                       ‫احلقوقيــة الثانيــة مبحكمــة االســتئناف مبنطقــة عســير‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة العامــة‬\n     ‫بنجــران حضــر ‪ ........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n     ‫‪ ........‬أصالــة عــن نفســه‪ ،‬وبالوكالــة عــن ‪ ........‬حامــل الســجل املدنــي‬\n\n‫‪71‬‬\n\f‫رقــم ‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل جنــران رقــم‬\n‫‪ .........‬يف ‪1433/5/16‬هــ‪ ،‬والتــي تخولــه حــق اســتالم مــا يخصــه‬\n‫مــن تركــة مورثــه ‪ ........‬واملطالبــة باملبالــغ املاليــة لــدى الغيــر وإقامــة‬\n‫الدعــاوى ودفعهــا واملرافعــة واملدافعــة والصلــح‪ ،‬وغيــر ذلــك‪ .‬وبصفتــه‬\n‫ا عــن ‪ ........‬و‪ ........‬و‪ ........‬و‪ ........‬بنــات ‪ ........‬مبوجــب الوكالــة‬\n                                                                              ‫وكيـ ً‬\n‫الصــادرة مــن كتابــة عــدل جنــران برقــم ‪ .........‬يف ‪1433/3/12‬هـ والتي‬\n‫تخولــه حــق اســتالم جميــع مــا لهــن مــن حقــوق واملطالبــة بهــا واملداعــاة‬\n‫واملخاصمــة وســماع الدعــاوى والــرد عليهــا وإقامــة البينــة والدفــع وقبــول‬\n‫احلكــم واالعتــراض عليــه يف أي قضيــة تقــام منهــن أو ضدهــن‪ ،‬وغيــر‬\n‫ذلــك‪ .‬وبالوكالــة عــن ‪ - ........‬ســعودي‪ -‬مبوجــب ســجل مدنــي رقــم‬\n‫‪ ........‬أصالــة عــن نفســه وبصفتــه الولــي الشــرعي علــى أختــه القاصــر‬\n‫‪ ........‬املولــودة يف ‪1420/7/15‬ه ـ مبوجــب صــك الواليــة رقــم ‪8/13‬‬\n‫وتاريــخ ‪1422/8/6‬ه ـ الصــادر مــن احملكمــة العامــة بنجــران مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب جــدة رقــم ‪.........‬‬\n‫تاريــخ ‪1433/5/24‬ه ـ والتــي تخولــه حــق اســتالم جميــع مالهمــا مــن‬\n‫حقــوق واملطالبــة بهــا واملداعــاة واملخاصمــة وســماع الدعــاوى والــرد‬\n‫عليهــا وإقامــة البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه وذلــك يف‬\n‫أي قضيــة تقــام منهــم أو ضدهــم أمــام أي محكمــة ويف أي جهــة وإنهــاء‬\n‫كافــة اإلجــراءات الشــرعية واإلداريــة وغيــر ذلــك‪ .‬وبالوكالــة عــن‬\n‫‪ ........‬و‪ ........‬ابنتــا ‪ ........‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫محافظــة اجلبيــل رقــم ‪ .........‬تاريــخ ‪1433/3/16‬ه ـ والتــي تخولــه حــق‬\n‫املطالبــة باملبالــغ املاليــة لــدى الغيــر وإقامــة الدعــاوى ودفعهــا واملرافعــة‬\n‫واملدافعــة والصلــح وقبــول احلكــم واالعتــراض عليــه وطلــب حلــف‬\n\n\n                                                                                        ‫‪72‬‬\n\f     ‫اليمــن واالســتالم فيمــا يخــص إرثهــم مــن مورثهــم ‪ ........‬وغيــر ذلــك‪.‬‬\n     ‫وبالوكالــة عــن ‪ ........‬ســعودي ســجل مدنــي رقــم ‪ ........‬والتــي تخولــه‬\n     ‫املطالبــة وإقامــة الدعــاوى واملرافعــة واملدافعــة وســماع الدعــاوى والــرد‬\n     ‫عليهــا واإلقــرار واإلنــكار والصلــح والتنــازل واإلبــراء وطلــب اليمــن‬\n     ‫ورده واالمتنــاع عنــه وإحضــار الشــهود والبينــات والطعــن فيهــا واإلجابــة‬\n     ‫واجلــرح والتعديــل والطعــن بالتزويــر وطلــب التحكيــم واملطالبــة بتنفيــذ‬\n     ‫األحــكام واالعتــراض علــى األحــكام وطلــب االســتئناف والتمــاس‬\n     ‫إعــادة النظــر وغيــر ذلــك‪ .‬وبالوكالــة عــن ‪ ........‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل جنــران رقــم ‪ .........‬وتاريــخ ‪1433/3/23‬ه ـ‬\n     ‫والتــي تخولــه حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة‬\n     ‫الدعاوى ضد الغير وإنهاء ما يلزم حضور موكلته يف كل دعوى تقام‬\n     ‫منهــا أو ضدهــا وغيــر ذلــك‪ .‬وبالوكالــة عــن ‪ ........‬مبوجــب الصــادرة مــن‬\n     ‫كتابــة عــدل جنــران رقــم ‪ .........‬وتاريــخ ‪1433/3/23‬ه ـ والتــي تخولــه‬\n     ‫حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى وغيــر‬\n     ‫ذلــك‪ .‬وبالوكالــة عــن ‪ ........‬ســجل مدنــي رقــم ‪ ........‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل جنــران رقــم ‪ .........‬وتاريــخ ‪1433/3/23‬ه ـ‬\n     ‫والتــي تخولــه حــق املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة‬\n     ‫الدعــاوى واســتخراج حجــج االســتحكام وصكــوك التملــك والقســمة‬\n     ‫وفــرز النصيــب واإلفــراغ للورثــة يف نصيبهــم وغيــر ذلــك‪ .‬وبالوكالــة عن‬\n     ‫‪ ........‬الصــادرة مــن كتابــة عــدل بقيــق رقــم ‪ ....‬وتاريــخ ‪1433/3/15‬ه ـ‬\n     ‫والتــي تخولــه حــق املطالبــة واملداعــاة واملخاصمة وســماع الدعــاوي والرد‬\n     ‫عليهــا وإقامــة البينــة والدفــع وقبــول احلكــم واالعتــراض عليــه وغيــر‬\n     ‫ذلــك‪ .‬وحضــر حلضــوره املدعــى عليــه ‪ ........‬حامــل الســجل املدنــي رقــم‬\n\n\n‫‪73‬‬\n\f‫‪ ، ........‬ولــم يحضــر املدعــى عليــه الثانــي ‪ ........‬حامــل الســجل املدنــي‬\n‫رقــم ‪ ، ........‬ولــم يردنــي مــن محضــري اخلصــوم مــا يفيــد تبلغــه مبوعــد‬\n‫ا يف دعــواه‪:‬‬   ‫هــذه اجللســة‪ ،‬وقــد ادعــى املدعــي أصالــة ووكالــة قائ ـ ً‬\n‫إن مورثــي ومــورث املدعــى عليــه تــويف يف ‪1422/1/15‬هــ‪ ،‬وخلــف مــن‬\n‫ضمــن تركتــه عقــار جتــاري مكــون مــن شــقق ســكنية ومحــات‬\n‫جتاريــة‪ ،‬وهــو مملــوك بالصــك الصــادر مــن كتابــة عــدل جنــران‬\n‫برقــم (‪ )298‬وتأريــخ ‪1399/1/18‬هــ‪ ،‬وكذلــك عقــار آخــر ســكني‬\n‫مكــون مــن ســت شــقق ســكنية‪ ،‬وهــو مملــوك بالصــك الصــادر مــن‬\n‫كتابــة عــدل جنــران رقــم (‪ )125‬وتأريــخ بــدون‪ ،‬وقــد قــام املدعــى عليــه‬\n‫احلاضــر أخــي ‪ ........‬باالســتيالء ووضــع اليــد علــى العقــار األول مــن‬\n‫تأريــخ ‪1425/3/15‬ه ـ وقــام بأخــذ ريعهــا وســكن فيهــا بــدون أن يســلم‬\n‫للورثــة أجــرة الشــقتني اللتــن ســكن فيهمــا‪ ،‬كمــا قــام املدعــى عليــه‬\n‫الثانــي الغائــب أخــي ‪ ........‬باالســتيالء ووضــع اليــد علــى العقــار الثانــي‬\n‫وأخــذ ريعــه مــن حــن وفــاة مورثنــا‪ ،‬حتــى حينــه‪ .‬وأطلــب إلــزام املدعــى‬\n‫عليهمــا بتســليمي وموكلــي نصيبنــا مــن إرث مورثنــا مــن ريــع هذيــن‬\n‫العقاريــن مــن حــن اســتالم كل واحــد منهمــا للعقــار فقــط‪ ،‬وأمــا‬\n‫قســمة العقــار فلدينــا دعــوى منظــورة حالي ـ ًا لــدى املكتــب القضائــي‬\n‫الثالــث باحملكمــة العامــة بنجــران أمــام فضيلــة القاضــي ‪ ، ........‬ولــم‬\n‫يصــدر فيهــا أي حكــم حتــى حينــه‪ .‬هكــذا ادعــى كمــا أبــرز صــورة‬\n‫مصدقــة مــن صــك حصــر الورثــة الصــادر مــن هــذه احملكمــة برقــم ‪.....‬‬\n‫يف ‪1422/2/14‬هــ‪ ،‬وباطالعــي عليهــا وجدتهــا تتضمــن وفــاة ‪........‬‬\n‫بتاريــخ ‪1422/1/15‬هــ‪ ،‬وانحصــار إرثــه يف زوجاتــه ‪ ، ........‬و‪، ........‬‬\n‫و‪ ........‬ويف أوالده البالغــن وهــم‪ ... :‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪...‬‬\n\n\n                                                                                         ‫‪74‬‬\n\f     ‫و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ...‬و‪ ،...‬ويف أوالده‬\n     ‫القاصريــن مــن زوجتــه ‪ ، ...‬وهــم‪ ... :‬املولــود يف ‪1409/8/13‬ه‪ ،‬و‪...‬‬\n     ‫املولــود بتأريــخ ‪1415/2/9‬هــ‪ ،‬و‪ ...‬املولــود بتاريــخ ‪1418/6/15‬هــ‪... ،‬‬\n     ‫املولــودة بتأريــخ ‪1408/5/27‬هــ‪ ،‬و‪ ...‬املولودة بتأريخ ‪1421/12/21‬هـ‪،‬‬\n     ‫و‪ ...‬املولــودة بتاريــخ ‪1420/7/4‬هــ‪ .‬وبعــرض دعــواه علــى املدعــى عليــه‬\n     ‫األول أجــاب بقولــه‪ :‬إن مــا ذكــره املدعــي أصالــة ووكالــة يف دعــواه‬\n     ‫ضــدي مــن أن العقــار املذكــور يف دعــواه حتــت حيازتــي وتصــريف مــن‬\n     ‫تأريــخ ‪1425/3/15‬هــ‪ ،‬وأننــي أســكن يف شــقتني منــه‪ ،‬وأننــي أســتلم‬\n     ‫ريــع هــذا العقــار فهــذا كلــه صحيــح‪ ،‬وســكني هــو برضــا كل الورثــة‪.‬‬\n     ‫هكــذا أجــاب‪ .‬فعليــه‪ ،‬وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪،‬‬\n     ‫وبنــاء علــى أن هــذه الدعــوى هــي دعــوى يف ريــع عقــار هــو جــزء مــن‬\n     ‫التركــة‪ ،‬ومبــا أن دعــوى التركــة ال تــزال منظــورة لــدى فضيلــة الشــيخ‬\n     ‫‪ ، ...‬وال يصــح أن تنظــر أكثــر مــن دعــوى يف قســمة تركــة واحــدة يف‬\n     ‫آن واحــد‪ ،‬حيــث أن يف هــذا تشــتيت للخصــوم وللمحكمــة كذلــك‪،‬‬\n     ‫ـاض واحــد توحيــد للعمــل واإلجــراء‪ ،‬ومبــا أن معاملــة‬   ‫ويف نظرهــا مــن قـ ٍ‬\n     ‫قســمة التركــة أحليــت إلــى فضيلتــه أوالً‪ ،‬لذلــك كلــه فقــد رأيــت أن‬\n     ‫هــذه القضيــة هــي مــن اختصــاص فضيلــة الشــيخ ‪ ، ...‬وجــرت الكتابــة‬\n     ‫منــا إلــى فضيلــة رئيــس احملكمــة إلحالــة املعاملــة إلــى فضيلتــه بخطابنــا‬\n     ‫رقــم ‪ 33473260‬يف ‪1433/7/29‬هــ‪ ،‬حســب املــادة (‪ )6/11‬مــن‬\n     ‫نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة‪ ،‬ثــم عــادت لنــا املعاملــة‬\n     ‫بخطــاب فضيلــة ‪ ...‬رقــم ‪ .........‬وتأريــخ ‪1433/9/5‬ه ـ املتضمــن طلــب‬\n     ‫إعــادة املعاملــة إلــى املكتــب القضائــي التاســع‪ ،‬وحيــث حتقــق التدافــع‬\n     ‫املنصــوص عليــه يف املــادة الرابعــة والســبعني مــن نظــام املرافعــات‬\n\n\n‫‪75‬‬\n\f‫الشــرعية والئحتــه التنفيذيــة‪ ،‬وملــا تقــدم كلــه فقــد حكمــت بصــرف‬\n‫النظــر عــن هــذه الدعــوى لعــدم االختصــاص‪ ،‬وقــررت بعــث املعاملــة‬\n‫إلــى محكمــة االســتئناف للفصــل يف ذلــك‪ ،‬وأعلمــت الطرفــن بذلــك‪،‬‬\n‫وبــاهلل التوفيــق‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                          ‫وســلم‪ .‬حــرر يف ‪1434/03/02‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بنجــران برقــم ‪.........‬‬\n‫وتاريــخ ‪1434/3/3‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ ‪/‬‬\n‫‪ ...‬برقــم ‪ .........‬يف ‪1434/3/2‬ه ـ اخلــاص بدعــوى ‪ /‬ورثــة ‪ ...‬ضــد ‪ ... /‬و‪...‬‬\n‫ابنــي ‪ ...‬بشــأن عقــار املتضمــن حكــم فضيلتــه مبــا هــو مــدون بالقــرار‬\n‫ومفصــل فيــه ‪ ،‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n‫املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                           ‫وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪76‬‬\n\f       ‫تاريخه‪1434/2/24 :‬هـ‬\n                       ‫ُ‬   ‫الص ِّك‪3445903:‬‬  ‫َر ْق ُم َّ‬\n                         ‫عوى‪3459534:‬‬   ‫الد َ‬  ‫َر ْق ُم َّ‬\n                 ‫صديق من محكم ِة‬\n                              ‫ِ‬   ‫َر ْق ُم قرا ِر ال َّت‬\n      ‫تاريخه‪1434/4/13:‬هـ‬\n                     ‫ُ‬                  ‫ِ‬\n                          ‫االستئناف‪34186029:‬‬\n\n\n     ‫ـارج اململكـ ِة ‪َ -‬صـ ْـر ُف ال َّنظـ ِر‬\n                                         ‫عقــار خـ َ‬\n                                                  ‫بعــن َ‬ ‫ـار‪ -‬املُ َطالبـ ُة َ‬\n                                                                            ‫عقـ ٌ‬\n                                                                                ‫اختصــاص ‪َ -‬‬\n                                                            ‫الدعـ َوى لعــد ِم الواليـ ِة َ‬\n                                                  ‫القضائيـةِ‪.‬‬                           ‫عـ ِـن َّ‬\n\n\n\n     ‫أن‬         ‫الشــرعي ِة ا َّلتــي تنـ ُّ‬\n     ‫ـص ع َلــى َّ‬                       ‫املــوا ُّد (‪ )26،25،24‬مِ ــن ِنظــا ِم املُرافعــاتِ َّ‬\n     ‫ـس للمحاكـ ِـم‬  ‫ـارج املَملك ـ ِة ليـ َ‬\n                                           ‫بعقــا ٍر خـ َ‬\n                                                       ‫العيني ـ َة املتع ِّلق ـ َة َ‬‫الدعــا َوى َ‬\n                                                                                                ‫َّ‬\n                                                                ‫عليهــا‪.‬‬\n                                                                    ‫َ‬        ‫الســعودي ِة والي ـ ٌة‬\n\n\n\n\n     ‫وهي‬\n       ‫املد َعى علي َها َ‬    ‫متزوجــا مـ َـن َّ‬\n                                            ‫ً‬         ‫كان‬\n                                                        ‫َ‬            ‫موك َلـ ُه‬\n                                                                            ‫أن ّ‬  ‫املدعِ ــي وكالـ ًة َّ‬    ‫ا َّد َعــى َّ‬\n     ‫املد َعــى علي َهــا بشــرا ِء َمنــزلٍ مكـ َّـونٍ مِ ــن‬  ‫ـام هـ َـو ووالـ ُـد َّ‬            ‫ُأ ُّم أوالده ‪َ ،‬‬\n                                                                                         ‫ولقــد قـ َ‬\n     ‫ـترى خمس ـ َة‬   ‫كمــا أ َّنــه اشـ َ‬ ‫ـام ببنــا ِء ثالث ـ ِة أدوا ٍر فوقَ ــه‪َ ،‬‬           ‫َدور ْيـ ِـن‪ ،‬ثـ َّـم قـ َ‬\n     ‫ولقــد‬‫املد َعــى عليهــا‪َ ،‬‬   ‫جميعهــا باسـ ِـم َّ‬\n                                                      ‫َ‬              ‫ـف الفــدانِ ‪ ،‬وســجلَها‬       ‫أفدن ـ ٍة ونصـ َ‬\n             ‫املدعِ ــي وكال ـ ًة‪ ،‬ولـ ْـم حتضـ ِـر َّ‬\n     ‫املد َعــى‬                                               ‫طلقهــا بعـ َـد ذلـ َـك‪ ،‬وقــد حضـ َـر َّ‬               ‫َ‬\n     ‫األرض الزراعي ـ ِة‬ ‫ِ‬       ‫املد َعــى علي َهــا بإعــاد ِة‬    ‫ـزام َّ‬   ‫املدعِ ــي إلـ َ‬\n                                                                                            ‫علي َهــا‪ ،‬وطلـ َـب َّ‬\n     ‫الشــرعي ِة‬\n               ‫ـات َّ‬  ‫ـام املُرافعـ ِ‬ ‫مبوجـ ِـب املــوا ِّد (‪ )26 ،25 ،24‬مِ ــن ِنظـ ِ‬               ‫واملنــزلِ ‪ُ ،‬‬\n     ‫ـارج اململك ـ ِة‬ ‫بعقــا ٍر خـ َ‬ ‫العيني ـ َة املتع ِّلق ـ َة َ‬‫ـاوى َ‬      ‫الدعـ َ‬\n                                                                                    ‫أن َّ‬ ‫ـص ع َلــى َّ‬   ‫ا َّلتــي تنـ ُّ‬\n     ‫ـدر احلكـ ُـم بــر ِّد دعـ َـوى‬  ‫ـس للمحاكـ ِـم الســعودي ِة واليـ ٌة علي َهــا؛ لــذا صـ َ‬                     ‫ليـ َ‬\n     ‫ـدق ا ُحلكـ ُـم مــن‬  ‫ُكـ ِـم وصـ َ‬   ‫املدعِ ــي وكال ـ ًة ع َلــى احل ْ‬         ‫ـرض َّ‬  ‫املدعِ ــي ‪ ،‬واعتـ َ‬      ‫َّ‬\n\n‫‪77‬‬\n\f                                                        ‫ِ‬\n                                                       ‫ـتئناف‪.‬‬‫محكم ـ ِة االسـ‬\n\n\n\n\n‫ـدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬    ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n‫ـاء علــى املعاملــة احملالــة إلينــا مــن قِ بــل فضيلــة‬\n                                                        ‫مبحافظــة جــدة‪ ،‬وبنـ ً‬\n‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪.........‬‬\n‫وتاريــخ ‪1434/02/05‬ه ـ املقيــدة باحملكمــة برقــم ‪ .........‬وتاريــخ‬\n‫‪1434/02/05‬هــ‪ ،‬ففــي يــوم الســبت ‪1434/02/23‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة ‪ 10 : 15‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪ ...‬بصفتــه وكيـ ًـا عــن ‪ ...‬بصــك الوكالــة ذي الرقــم ‪.........‬‬\n‫والتاريــخ ‪1433/10/22‬ه ـ املجلــد ‪ .........‬الصــادر عــن كتابــة العــدل‬\n‫الثانيــة بجنــوب محافظــة جــدة لســماع دعــواه علــى ‪ ...‬بشــأن دعــوى‬\n‫ملكيــة عقــار‪ ،‬ولــم حتضــر املدعــى عليهــا وال مــن ميثلهــا‪ ..‬وباالطــاع‬\n‫علــى صحيفــة الدعــوى املرفقــة باملعاملــة ُوجــد أن نصهــا مــا يلــي‪« :‬إن‬\n‫املدعــى عليهــا كانــت زوجتــي وهــي ال تــزال ُأ َّم عيالــي‪ ،‬وهــي مصريــة‬\n‫اجلنســية‪ ،‬وكانــت تــزور أهلهــا‪ ..‬وعندمــا كبــرت أســرتي طلبــت منــي‬\n      ‫(‪ )1‬بنــاء دور علــوي علــى منــزل والدهــا بعــد موافقتــه علــى ذلــك‪.‬‬\n‫(‪ )2‬قمــت مبشــاركة والدهــا يف شــراء منــزل مــن دوريــن مجــاور ملنزلــه‪.‬‬\n‫(‪ )3‬ثــم قمــت ببنــاء ثالثــة أدوار عليــه لطلبهــا‪ )4( .‬وأخيـ ًـرا‪ ،‬شــراء أرض‬\n‫زراعيــة مســاحتها خمســة أفدنــة ونصــف الفــدان‪ ،‬تقــوم بتأجيرهــا‬\n‫لوالدهــا حتــى توفــاه اهلل منــذ ‪ 5‬ســنوات‪ )5( .‬ثــم قمــت بتســجيل‬\n‫جميــع مــا قمــت ببنائــه وشــرائه باســمها لكونهــا ُأ َّم عيالــي وشــريكة‬\n‫ـدي‬\n ‫حياتــي‪ ،‬وألن النظــام يف مصــر ال يســمح بتســجيله باســمي وليــس لـ َّ‬\n                                                                                    ‫‪78‬‬\n\f     ‫أي مســتند عليهــا أو أي بينــة مكتوبــة لكونهــا كانــت يف عصمتــي‬\n     ‫وشــريكة حياتــي و ُأ َّم عيالــي الثمانيــة بعــد انفصالنــا‪ ،‬أطلــب احلكــم‬\n     ‫عليهــا بإعــادة األرض الزراعيــة (خمســة أفدنــة ونصــف الفــدان) واملنــزل‬\n     ‫نصــا‪ .‬وبســؤال املدعــي وكال ًة‬  ‫املكــون مــن خمســة أدوار إلـ َّـي) ا‪.‬هــ‪ .‬نقــل ًّ‬\n     ‫عــن مــكان العقــار املذكــور يف الدعــوى أجــاب قائـ ًـا إنــه يقــع بدولــة‬\n     ‫ـاء علــى مــا تقـ َّـدم مــن دعــوى املدعــي وكالـ ًة‬  ‫مصــر؛ هكــذا أجــاب‪ .‬وبنـ ً‬\n     ‫واملتضمنــة مطالبتــه بعــن عقــار خــارج اململكــة‪ ،‬وبعــد االطــاع علــى‬\n     ‫نظــام املرافعــات الشــرعية يف املــواد (الرابعــة والعشــرين واخلامســة‬\n     ‫والعشــرين والسادســة والعشــرين) التــي تنــص علــى أن الدعــاوى العينيــة‬\n     ‫املتعلقــة بعقــار خــارج اململكــة ليــس للمحاكــم الســعودية واليــة عليهــا‪،‬‬\n     ‫ـدي أن للمدعــي وكال ـ ًة املطالبــة بعقــار خــارج اململكــة يف‬        ‫فلــم يثبــت لـ َّ‬\n     ‫رددت دعــواه وبــه حكمــت‪ ،‬وبإعالنــه‬     ‫ُ‬     ‫محاكــم اململكــة‪ ،‬وعليــه فقــد‬\n     ‫عليــه اعتــرض وطلــب التمييــز واســتعد بتقــدمي الئحــة اعتراضيــة‪ ،‬فأفهــم‬\n     ‫بــأن عليــه مراجعــة احملكمــة يــوم اإلثنــن ‪1434/02/25‬ه ـ الســتالم‬\n     ‫يومــا ولــم يقــدم‬‫نســخة احلكــم وإذا فــات علــى ميعــاد االعتــراض ثالثــون ً‬\n     ‫الئحتــه االعتراضيــة فسيســقط حقــه يف االعتــراض واكتســب احلكــم‬\n     ‫القطعيــة‪ ،‬واختتمــت اجللســة يف الســاعة العاشــرة وخمــس وأربعــن‬\n     ‫دقيقــة‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                         ‫وصحبــه وســلم‪ُ .‬حــرر يف ‪1434/02/23‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده بعــد‪ ،‬ففــي يــوم األحــد ‪1434/03/01‬ه ـ افتتحــت‬\n     ‫اجللســة يف الســاعة الواحــدة‪ ،‬وفيهــا حضــر املدعــي وكال ـ ًة ‪ ...‬املثبتــة‬\n     ‫ـابقا واســتلم نســخة احلكــم‪ ،‬وأفهــم بتعليمــات‬            ‫هويتــه ووكالتــه سـ ً‬\n     ‫التمييــز كمــا يف اجللســة املاضيــة فتفهــم ذلــك‪ ،‬واختتمــت اجللســة‪ ..‬ثــم‬\n\n\n‫‪79‬‬\n\f‫ـدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة مبحافظــة جــدة القائــم بعمــل‬         ‫لـ َّ‬\n‫فضيلــة الشــيخ ‪ ...‬خــال فتــرة انتدابــه لــدورة وســائل اإلثبــات‪ ،‬واملقامــة‬\n‫مبدينــة الريــاض التــي تبــدأ بتاريــخ ‪1434/03/14‬ه ـ وتنتهــي بتاريــخ‬\n‫‪1434/03/18‬هــ‪ ..‬ففــي يــوم الثالثــاء ‪1434/03/17‬ه ـ افتتحــت اجللســة‬\n‫يف الســاعة احلاديــة عشــرة وخمــس وأربعــن دقيقــة؛ وفيهــا حضــر املدعــي‬\n‫ـابقا‪ ،‬وقــدم الئحتــه االعتراضيــة‬    ‫وكال ـ ًة ‪ ...‬املثبتــة هويتــه ووكالتــه سـ ً‬\n‫املقيــدة يف احملكمــة برقــم ‪ .........‬وتاريــخ ‪1434/03/17‬ه ـ واملكونــة‬\n‫ـدي‬\n ‫ورفعــت اجللســة لدراســتها‪ ،‬واختتمــت‪ ..‬ثـ َّـم لـ َّ‬‫مــن ورقتــن مبرفقاتهــا‪ُ ،‬‬\n‫أنــا ‪ ...‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة‪ .‬ففــي يــوم الثالثــاء‬\n‫‪1434/04/02‬ه ـ افتتحــت اجللســة يف الســاعة التاســعة وخمــس وأربعــن‬\n‫دقيقــة‪ ،‬وباالطــاع علــى الالئحــة االعتراضيــة املُقدمــة مــن قِ بــل وكيــل‬\n‫املدعــي لــم أجــد بهــا مــا يؤثــر علــى مــا حكمــت بــه؛ لــذا قــررت رفــع‬\n‫كامــل املعاملــة مــع الصــك وصــورة مصدقــة مــن الضبــط إلــى محكمــة‬\n‫االســتئناف‪ ،‬واختتمــت اجللســة يف الســاعة العاشــرة‪ ،‬وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف‬\n                                                                ‫‪1434/04/06‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪ :‬فقــد‬\n‫جــرى منــا نحــن قُ ضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن قِ بــل فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جــدة املســاعد برقــم ‪.........‬وتاريــخ‬\n‫‪1434/04/08‬ه ـ املرفــق بهــا الصــك الصــادر عــن فضيلــة الشــيخ ‪...‬‬\n‫القاضــي باحملكمــة العامــة مبحافظــة جــدة املســجل برقــم ‪.........‬‬\n‫وتاريــخ ‪1434/02/24‬ه ـ املتضمــن دعــوى ‪ ...‬ضــد‪ ،...‬وبدراســة الصــك‬\n\n\n                                                                                           ‫‪80‬‬\n\f     ‫وص ــورة ضبط ــه والئحتــه االعتراضيــة ـ مت إقــرار املوافق ــة عل ــى احلكــم‪.‬‬\n     ‫واهلل املوفــق‪ ،‬وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n\n\n\n\n‫‪81‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":70,"source_page_end":81,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2112f68a332c131844e78ecd881b63713d98a01d30b305b69797ed53d54ba770","normalized_text_hash":"4f92f1be2db80bd8f6cebc50bc6770e73e93c6dbb25850fc179d0388818c5e3a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p70-3453923"},{"id":"532db332-12c9-5f3a-bb16-c689a89c19fb","document_type":"judgment","category":"judicial","subcategory":"general","title":"ن احملكم ة إصاب ة -تنا ز ع يف االخ تص اص ب صاص -د ي ة أ ر ش اخت","document_number":"3430162","case_number":"3473010","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة احلمد هلل وحده","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/21","year":"1434","subject":"ن احملكم ة إصاب ة -تنا ز ع يف االخ تص اص ب صاص -د ي ة أ ر ش اخت","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/8/21 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3430162 :‬‬\n                    ‫َر ْق ُم الدعوى‪3473010 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34301627‬تاريخه‪1434/8/21 :‬هـ‬\n\n\n‫ن احملكم ـ ِة‬           ‫إصاب ـ ٍة ‪ -‬تنــا ُز ٌع يف االخ ِتصـ ِ‬\n                ‫ـاص ب ـ َ‬                                            ‫ِصــاص ‪ِ -‬د َي ـ ُة َأ ْر ِش َ‬   ‫اخت َ‬\n‫العــام‬\n      ‫نظـ ُـر مـ َـع احلـ ِّـق َ‬‫ـاص ُي َ‬ ‫اجلزائي ـ ِة ـ احلـ ُّـق اخلـ ُّ‬\n                                                                  ‫َّ‬                ‫العام ـ ِة واحملكم ـ ِة‬\n                                                                                                         ‫َّ‬\n‫دون ال َّنظ ـ ِر إلــى مِ قــدا ِر املبلـ ِـغ‬\n                                           ‫الدع ـ َوى َ‬ ‫عليهــا َّ‬\n                                                               ‫َ‬         ‫أي مرحل ٍــة كا َنـ ْـت‬       ‫يف ِّ‬\n‫ـتمرار‬\n ‫َ‬         ‫العــام ال مينـ ُـع االسـ‬‫ـدور ُحكـ ٍـم نِهائـ ٍّـي يف احلـ ِّـق َ‬ ‫املُطالـ ِـب ب ـ ِه ـ ُصـ ُ‬\n‫ـاص ال يلــز ُم مِ نــه‬‫احلكـ ُـم يف تنــاز ِع االخ ِتصـ ِ‬  ‫ـاص ـ ُ‬     ‫يف َدع ـ َوى احلـ ِّـق اخلـ ِّ‬\n‫ـاص‬ ‫احلكـ ِـم ِف تنــا ُز ِع االخ ِتصـ ِ‬       ‫الدع ـ َوى ـ مِ ــن ُشـ ِ‬\n                                            ‫ـروط ُ‬                                ‫ـرف َّ‬   ‫ـور َطـ َ‬\n                                                                                                 ‫ُحضـ ُ‬\n               ‫ـرف ال َّنظ ـ ِر لعــد ِم االخ ِتصـ ِ‬\n            ‫ـاص‪.‬‬                                       ‫حصــولُ التدافـ ِـع ـ احلكـ ُـم بصـ ِ‬\n\n\n\n\n                                     ‫‪ -1‬املا َّد ُة (‪ )148‬مِ ن نِظا ِم اإلجراءاتِ اجلزائيةِ‪.‬‬\n                                       ‫‪ -2‬املا َّد ُة (‪ )22‬مِ ن نِظا ِم اإلجراءاتِ اجلزائيةِ‪.‬‬\n                                                ‫‪ -3‬املا َّد ُة (‪ )74‬مِ ن نِظا ِم املُرافعاتِ َّ‬\n                                          ‫الشرعيةِ‪.‬‬\n\n\n\n\n‫املدعِ ــي ِضـ َّـد‬   ‫العام ـ ِة لل َّنظـ ِـر يف َدعـ َـوى َّ‬\n                                                          ‫َّ‬      ‫املكم ـ ِة‬ ‫ُفتحـ ِـت اجلَلس ـ ُة يف َ‬\n‫فيمــا يتع َّلـ ُـق ب ـ َأ ْر ِش‬\n                             ‫ـاص َ‬   ‫ـوص املُطالب ـ ِة باحلـ ِّـق ا َخلـ ِّ‬‫بخصـ ِ‬ ‫املد َعــى علي ـ ِه ُ‬‫َّ‬\n‫مت نظـ ُـر ُه وا ُحلكـ ُـم‬    ‫العــام َّ‬\n                                       ‫إن احلـ َّـق َ‬    ‫املدعِ ــي؛ حيـ ُ‬\n                                                     ‫ـث َّ‬               ‫اإلصاب ـ ِة ا َّلتــي حلقـ ِـت َّ‬\n‫ـث املعامل ـ ِة للمحكم ـ ِة‬         ‫في ـ ِه مِ ــن قِ بـ ِـل احملكم ـ ِة اجلزائي ـةِ؛ لـ َـذا جـ َـرى بعـ ُ‬\n‫ـاص ـ لكــن عــا َد ْت مـ َـن احملكم ـ ِة اجلزائي ـ ِة‬               ‫بحكـ ِـم االخ ِتصـ ِ‬ ‫اجلزائي ـ ِة ُ‬\n\n                                                                                                               ‫‪82‬‬\n\f     ‫ِصاصهــم َو ْف ًقــا للمــوا ِّد (‪22‬و‪128‬و‪ )148‬مِ ــن‬                      ‫ـأن املُعاملـ َة خارجـ ٌة عـ ِـن اخت ِ‬               ‫بـ َّ‬\n     ‫أن املــا َّد َة‬‫مبــا َّ‬\n                           ‫العام ـ ُة َ‬\n                                      ‫َّ‬           ‫رت احملكم ـ ُة‬     ‫ـراءات اجلزائي ـةِ‪ ، .‬وقـ َّـر ِ‬ ‫ِ‬           ‫ـام اإلجـ‬ ‫ِنظـ ِ‬\n     ‫ـرر‬\n       ‫الضـ ُ‬   ‫حلق ـ ُه َّ‬\n                          ‫أن َملــن َ‬     ‫نصـ ْـت ع َلــى َّ‬     ‫ـراءات اجلزائي ـ ِة َّ‬   ‫ِ‬    ‫ـام اإلجـ‬   ‫(‪ )148‬مِ ــن ِنظـ ِ‬\n     ‫ـداره‬‫مهمــا بلـ َغ مِ قـ ُ‬  ‫ـاص َ‬        ‫بحقــه اخلـ ِّ‬ ‫ولوا ِر ِثــه مِ ــن بعــدِ ه أنْ ُيطالـ َـب ِّ‬    ‫مـ َـن اجلرميـ ِة َ‬\n     ‫أي حــالٍ كا َنـ ْـت‬         ‫الدعـ َـوى اجلزائي ـ ِة يف ِّ‬          ‫أمامهــا َّ‬  ‫ـام احملكم ـ ِة املنظــو ِر َ‬               ‫أمـ َ‬\n     ‫ـراءات اجلزائيـ ِة‬ ‫ِ‬           ‫ـام اإلجـ‬    ‫ـاء ع َلــى املــا َّد ِة (‪ )22‬مِ ــن ِنظـ ِ‬ ‫الدعـ َـوى ‪ ،‬وبنـ ً‬        ‫علي َهــا َّ‬\n     ‫العام ـ ِة ال مينـ ُـع مـ َـن‬\n                              ‫َّ‬              ‫الدعـ َـوى‬ ‫كـ ٍـم نِهائـ ٍّـي يف َّ‬    ‫ـدور ُح ْ‬\n                                                                                            ‫أن ُصـ َ‬     ‫تضم َنــت َّ‬‫َّ‬       ‫التــي‬\n     ‫ـام‬‫ـاء علــى املــا َّد ِة (‪ )74‬مــن ِنظـ ِ‬               ‫ـاص‪ ،‬وبنـ ً‬   ‫االســتمرا ِر يف َد ْعـ َـوى احلـ ِّـق اخلـ ِّ‬\n     ‫ـرف‬ ‫بصـ ِ‬              ‫التدافـ ِـع؛ لـ َـذا َصـ َـد َر احل ْ‬\n                    ‫ُكـ ُـم َ‬                                       ‫ُ‬            ‫ولتحقـ ِـق‬\n                                                                                       ‫ُّ‬       ‫الشــرعيةِ‪،‬‬   ‫ـات َّ‬    ‫املُرافعـ ِ‬\n     ‫ـاص‬   ‫ـاص‪ ،‬وأ َّنهــا مِ ــن اخ ِتصـ ِ‬                ‫ـدم االخ ِتصـ ِ‬      ‫الدعـ َـوى لعـ ِ‬ ‫ال َّنظـ ِـر َعــن هــذ ِه َّ‬\n     ‫الدعـ َـوى‬   ‫ُكـ ِـم يف َّ‬      ‫اضــي باحملكمـ ِة اجلزائيـ ِة ُمصــد ِر قَ ـ َـرار احل ْ‬                    ‫الق ِ‬\n                                                                                                                    ‫فضيلـ ِة َ‬\n                                            ‫ِ‬\n                                         ‫ـتئناف‪.‬‬        ‫العام ـ ِة ‪ ،‬وصــدق ا ُحلكـ َـم مــن محكم ـ ُة االسـ‬                   ‫َّ‬\n\n\n\n\n     ‫ـدي أنا‪ ...‬القاضي يف احملكمة العامة مبكة‬          ‫احلمــد هلل وحــده وبعــد‪ ،‬فلـ َّ‬\n     ‫املالــة إلينــا مــن قِ بــل فضيلــة رئيــس‬‫ـاء علــى املعاملــة ُ‬\n                                                                    ‫املكرمــة‪ ،‬وبنـ ً‬\n     ‫احملكمة العامة مبكة املكرمة برقم ‪ .........‬وتاريخ ‪1434/02/13‬هـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ .........‬وتاريــخ ‪1434/02/12‬هــ‪ ..‬ويف يــوم‬\n     ‫األحــد املوافق‪1434/08/21‬ه ـ ُفتحــت اجللســة بشــأن دعــوى‪ ...‬ضــد‪...‬‬\n     ‫بخصــوص املطالبــة باحلــق اخلــاص فيمــا يتعلــق بديــة إصابــات‪ ..‬وحيــث‬\n     ‫إن هــذه املعاملــة ســبق احلكــم فيهــا باحلــق العــام مــن قِ بــل الشــيخ‪...‬‬\n     ‫القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة مبوجــب قــراره‬\n     ‫رقــم ‪ .........‬يف ‪1433/07/30‬هــ؛ لــذا فقــد جــرى بعــث املعاملــة إلــى‬\n\n‫‪83‬‬\n\f‫احملكمــة اجلزائيــة بحكــم االختصــاص إال أنهــا عــادت بخطابهــم رقــم‬\n‫‪ .........‬يف ‪1434/07/30‬ه ـ واملتضمــن اإلفــادة بــأن املعاملــة خارجــة عــن‬\n‫وفقــا للمــواد (‪22‬و‪128‬و‪ )148‬مــن نظــام اإلجــراءات‬     ‫دائــرة اختصاصهــم ً‬\n‫وفقــا خلطــاب وكيــل وزارة العــدل للشــؤون القضائيــة املــؤرخ‬      ‫اجلزائيــة ً‬\n‫ـاء علــى مــا تقــدم ولصــدور حكــم يف الدعــوى‬     ‫يف ‪1425/01/18‬ه ـ فبنـ ً‬\n‫العامــة املتعلقــة بهــذه الدعــوى‪ ،‬كمــا يف القــرار املشــار إليــه أعــاه‪،‬‬\n‫ومبــا أن املــادة (‪ )148‬مــن نظــام اإلجــراءات اجلزائيــة نصــت علــى أن ملــن‬\n‫حلقــه ضــرر مــن اجلرميــة ولوارثــه مــن بعــده أن يطالــب بحقــه اخلــاص مهمــا‬\n‫بلــغ مقــداره أمــام احملكمــة املنظــورة أمامهــا الدعــوى اجلزائيــة يف أي‬\n‫ـدارا‬\n   ‫حــال كانــت عليهــا الدعــوى‪ ،‬ولكــون هــذه املــادة لــم حتــدد مقـ ً‬\n‫بعينــه للمطالبــة‪ ،‬ولكــون انتهــاء الدعــوى حالــة مــن أحــوال الدعــوى‪،‬‬\n‫ولكــون املــادة (‪ )22‬مــن نظــام اإلجــراءات اجلزائيــة تضمنــت أن صــدور‬\n‫حكــم نهائــي يف الدعــوى العامــة ال مينــع مــن االســتمرار يف دعــوى‬\n‫ـاء علــى املــادة الرابعــة والســبعني مــن نظــام املرافعــات‬\n                                                              ‫احلــق اخلــاص‪ ،‬وبنـ ً‬\n‫الشــرعية ولتحقــق التدافــع؛ لذلــك كلــه فقــد صرفــت النظــر عــن هــذه‬\n‫الدعــوى لعــدم االختصــاص‪ ،‬وأنهــا مــن اختصــاص فضيلــة ُمصــدر‬\n‫قــرار الدعــوى العامــة‪ ،‬وبذلــك كلــه حكمــت وأمــرت بإصــدار قــرار‬\n‫بهــذا‪ ،‬ورفعــه إلــى محكمــة االســتئناف لتدقيقــه حســب املتبــع‪ُ .‬حــرر‬\n‫يف ‪1434/08/21‬هــ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                ‫وصحبــه أجمعــن‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬يف يــوم األحــد املوافق‪1434/10/11‬ه ـ ُفتحــت‬\n‫اجللســة وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة‬\n‫ومرفــق بهــا القــرار رقــم ‪ .........‬يف‬\n                                        ‫برقــم ‪ .........‬يف ‪1434/09/17‬ه ـ ُ‬\n\n                                                                                       ‫‪84‬‬\n\f     ‫‪1434/08/21‬ه ـ ألصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الرابعــة‬\n     ‫مبحكمــة االســتئناف مبكة املكرمــة‪ ،‬واملتضمن املوافقة باألكثرية‬\n     ‫علــى احلكــم أعــاه‪ ،‬وللبيــان جــرى إحلاقــه‪ُ ..‬حــرر يف ‪1434/10/11‬هــ‪،‬‬\n            ‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪.‬‬\n     ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد‪ ،‬نحــن رئيس وقضاة‬\n     ‫الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقــة مكــة‬\n     ‫املكرمــة‪ ،‬جــرى مــن قِ ب ِلنــا االطــاع علــى القــرار رقــم ‪ .........‬وتاريــخ‬\n     ‫‪1434/8/21‬ه ـ الصــادر عــن فضيلــة الشــيخ‪ .../‬القاضــي باحملكمــة‬\n     ‫العامــة مبكــة املكرمــة‪ ،‬املتضمــن دعــوى املدعــي‪ .../‬ضــد‪ .../‬ســوداني‬\n     ‫اجلنســية يف قضيــة حــادث مــروري‪ ،‬احملكــوم فيــه مبــا دون باطنــه‪..‬‬\n     ‫وبدراســة القــرار وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكم‬\n     ‫بعــدم االختصــاص‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                                     ‫آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪85‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":82,"source_page_end":85,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e336ac3f836a7227a1ac0cc69b986dd86b4be6ac71e6adc4f5646037272e1ffc","normalized_text_hash":"56eaafff955b4b42fddf4daaa08ca7b986c07e04a4f55f091f762fdf03e78252","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p82-3430162"},{"id":"ac15c78e-e435-5b5d-b80f-d95da3e5932a","document_type":"judgment","category":"judicial","subcategory":"general","title":"افراء قطع ة ع لى ح د ح ر م املدين ة -اخ ت ار -ش عق اختصاص - املدع ي إفاد ة رسمي ة الطرف ن يف محل إقام ة املد عى علي ه -إبرا ز املد عى علي ه وكال ة إفاد ة رسمي ة مبحل إقام ة املد عى علي ه -إبرا ز املد عى علي ه يف محل إقام ته- بقول مبحل إقام ة موك له -الع بر ة اص احملل ي. املدع ي لعد م االخ تص رف ال نظ ر عن دع وى","document_number":"34233355","case_number":"32565145","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_a