166‬مِ ن نِظا ِم املُرافعاتِ َّ‬\n\n\n\n\n‫املد َعــى علي ـ ِه أصال ـ ًة‬ ‫ـتر ْت مـ َـن َّ‬ ‫ـأن موكل َت ـ ُه اشـ َ‬     ‫ا َّد َعــى امل َُّدعِ ــي وكال ـ ًة بـ َّ‬\n‫املدعِ ي‬ ‫طلب َّ‬   ‫ـف ريــالٍ ‪َ ،‬‬    ‫مت ذكـ ُـر وصفِ هــا) مببلـ ِـغ َســتمائ ِة ألـ ِ‬       ‫أرض ( َّ‬‫قطعـ َة ٍ‬\n‫ـدم ِص َّح ـ ِة‬ ‫املد َعــى علي ـ ِه وكال ـ ًة بعـ ِ‬   ‫ـاب َّ‬ ‫ـات هـ َـذا البيـ ِـع‪ ..‬وأجـ َ‬     ‫وكال ـ ًة إثبـ َ‬\n‫ـط ومِ ــن‬     ‫أن موك َل ـ ُه ميت ِلـ ُـك املُخطـ َ‬ ‫والصحيـ ُـح هـ َـو َّ‬\n                                                                        ‫الدعـ َـوى‪َّ ،‬‬        ‫ـاء يف َّ‬‫َمــا جـ َ‬\n‫ـرم املدين ـ ِة‬  ‫وألن هــذ ِه القطع ـ َة ع َلــى حـ ِّـد َحـ ِ‬ ‫ضم ِنــه القطع ـ ُة املذكــور ُة‪َّ ..‬‬\n‫فقــدِ ا ِّتفـ َـق موك ُل ـ ُه مـ َـع‬‫ـص لـ َـدى األمانــة ‪َ ،‬‬       ‫ـاج إلــى مراجع ـ ٍة وتخليـ ٍ‬        ‫وحتتـ ُ‬\n‫ـوم مبراجعـ ِة املُعاملـ ِة لـ َـدى األمانـةِ‪ ..‬وإ َذا انتهـ ْـت‬            ‫أخــو املُدعيـ ِة ع َلــى أنْ يقـ َ‬\n\n                                                                                                                       ‫‪122‬‬\n\f      ‫ـف‬  ‫ـاعا‪ ،‬ويدفـ ُـع كذلـ َـك ملوك ِلــه َســتمائ َة ألـ ِ‬                 ‫ـف هــذ ِه القطعـ ِة مشـ ً‬                 ‫ف َلـ ُه ِنصـ ُ‬\n      ‫ـف‬   ‫ـف ريــالٍ ‪ ،‬والباقِ ــي مائـ ُة ألـ ِ‬           ‫ريــالٍ ‪ ،‬دفـ َـع من َهــا أخــو املُدعيـ ِة َخمســمائ َة ألـ ِ‬\n      ‫ـوم لـ َـدى األمان ـةِ‪ ،‬ثـ َّـم طلـ َـب أخــو املُدعي ـ ِة إفــرا َغ هـ َـذا‬                     ‫ريــالٍ ُيدفـ ُـع كرسـ ٍ‬\n      ‫ـص املُعاملـةِ‪..‬‬      ‫يقـ ْـم بتخليـ ِ‬    ‫إن أخــا املُدعيـ ِة لـ ْـم ُ‬    ‫ـث َّ‬     ‫ا ُجلــز ِء ألخ ِتــه املُدعيـةِ؛ حيـ ُ‬\n      ‫املدعِ ــي‬  ‫األرض‪ ..‬أبــر َز َّ‬ ‫ِ‬            ‫ـادت األمان ـ ُة بأ َّن ـ ُه ال ميكـ ُـن إفــرا ُغ هــذ ِه‬          ‫وقَ ــد أفـ ِ‬\n      ‫املد َعــى علي ـهِ‪،‬‬      ‫ـأن َّ‬   ‫كمــا أبر َزإفــاد ًة رســمي ًة بـ َّ‬          ‫َ‬           ‫وكال ـ ًة عقـ َـد البيـ ِـع‪،‬‬\n      ‫املد َعــى عليـ ِه وكالـ ًة إفــاد ًة‬           ‫أصالـ ًة‪ ،‬مِ ــن ُســكانِ املدينـ ِة املنـ َّـورةِ‪ ..‬وأبــر َز َّ‬\n      ‫أجاب وكيــلُ املدعي ِة‬        ‫َ‬            ‫ـأن موك َلـ ُه مِ ــن ُســكانِ مدينـ ِة (بريــدة)؛‬                     ‫رســمي ًة بـ َّ‬\n      ‫ـارات يف (القصيــم)‬          ‫للمد َعــى علي ـهِ‪ ،‬أصال ـ ًة َعقـ ٌ‬              ‫ـون َّ‬     ‫ميكـ ُـن أنْ يكـ َ‬           ‫بأ َّن ـ ُه ِ‬\n      ‫املد َعــى علي ـ ِه وكال ـ ًة‪،‬‬          ‫إن َّ‬      ‫ـث َّ‬ ‫ـكن يف املدين ـ ِة املنـ َّـورةِ؛ حيـ ُ‬           ‫إال أ َّنـُـه يسـ ُ‬\n      ‫ـكن موك ِلــه منـ ُـذ أولِ َجلس ـةٍ‪،‬‬                   ‫الدعـ َـوى يف َمقـ ِـر َسـ ِ‬                  ‫ُم ِصـ ٌّـر ع َلــى َسـ ِ‬\n                                                                                                     ‫ـماع َّ‬\n      ‫ـدر‬\n        ‫فقــد َصـ َ‬       ‫الشــرعي ِة َ‬   ‫ـات َّ‬  ‫ـام املُرافعـ ِ‬      ‫ـن ‪ 10‬و‪ 34‬مِ ــن ِنظـ ِ‬           ‫ـاء ع َلــى املا َّدتـ ْ ِ‬\n                                                                                                                                  ‫وبنـ ً‬\n      ‫ـاص‬   ‫ـدم االخ ِتصـ ِ‬      ‫ـرف ال َّنظـ ِـر َعــن َدعـ َـوى امل َُّدعِ ــي وكالـ ًة‪ ،‬لعـ ِ‬                  ‫ا ُحلكـ ُـم بصـ ِ‬\n      ‫ـرر‬‫حضـ َـر يف َجلسـ ٍة ُأخـ َـرى وقـ َ‬               ‫املدعِ ــي‪ ،‬وكالـ ًة‪ ،‬ثـ َّـم َ‬       ‫ـرض َّ‬      ‫احمل ِّلــي‪ ،‬واعتـ َ‬\n      ‫ـاص‪،‬‬    ‫ـث املُعامل ـ ِة حملكم ـ ِة (بريــدة) لالخ ِتصـ ِ‬                          ‫مت بعـ ُ‬  ‫قناع َت ـ ُه با ُحلكـ ِـم‪ ..‬و َّ‬\n      ‫ـاء ع َلــى املــا َّد ِة‬\n                              ‫ـاص‪ ..‬وبنـ ً‬   ‫ـدم االخ ِتصـ ِ‬          ‫و ُأعيـ َـد ْت مِ ــن محكم ـ ِة (بريــدة) لعـ ِ‬\n      ‫ـث املُعامل ـ ِة إلــى محكم ـ ِة‬                  ‫مت بعـ ُ‬ ‫الشــرعي ِة َّ‬\n                                                                              ‫ـات َّ‬      ‫ـام املُرافعـ ِ‬     ‫‪ 2/74‬مِ ــن ِنظـ ِ‬\n      ‫ـتئناف‪.‬‬‫مت التصديـ ُـق ع َلــى ا ُحلكـ ِـم مِ ــن قِ بـ ِـل محكمـ ِة االسـ ِ‬                                         ‫االسـ ِ‬\n                                                                                                               ‫ـتئناف‪ ،‬و َّ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد‪ ،‬فلــدي أنــا ‪ ...‬القاضــي يف احملكمــة العامــة‬\n      ‫ـاء علــى املعاملــة احملالــة إلينــا مــن قِ بــل فضيلــة‬\n                                                              ‫باملدينــة املنــورة‪ ،‬وبنـ ً‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 32565145‬وتاريــخ‬\n\n‫‪123‬‬\n\f‫‪1432/11/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321532626‬وتاريــخ‬\n‫‪1432/11/27‬هــ‪ ..‬أنــه يف يــوم األحــد ‪1433/4/4‬ه ـ حضــر ‪...‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ...‬وكيـ ًـا عــن ‪ ...‬مبوجــب صــك الوكالــة‬\n‫الصــادر عــن كتابــة العــدل الثانيــة باملدينــة برقــم ‪ 70123‬وتاريــخ‬\n‫‪1432/11/26‬هــ‪ ،‬كمــا حضــر حلضــوره ‪ ...‬ســعودي بالســجل املدنــي‬\n‫رقــم ‪ ...‬وكيـ ًـا عــن ‪ ...‬ســعودي بالســجل املدنــي رقــم ‪ ...‬مبوجــب صــك‬\n‫الوكالــة الصــادر عــن كتابــة عــدل املدينــة الثانيــة برقــم ‪ 555‬وتاريــخ‬\n‫‪1432/1/2‬هــ‪ ،‬وكنــا قــد كتبنــا لعمــدة حــي ‪ ..........‬لإلفــادة عــن‬\n‫ســكن املدعــى عليــه بحســب إفــادة املدعــي أنــه يســكن بهــذا احلــي‬\n‫ا‪.‬هــ‪ ..‬فــورد اجلــواب مــن عمــدة حــي ‪ ........‬برقــم ‪/899‬أ ‪/‬ع‪ 331/‬يف‬\n‫‪1433/1/10‬هــ‪ ،‬وتضمــن قيــام العمــدة بالتحقــق مــن ســكن املذكــور‬\n‫ومــا أفــاد بــه املذكــور أنــه يســكن يف (بريــدة) حــي ‪ ...‬وال يســكن‬\n‫يف املدينــة‪ ،‬إال أنــه يأتيهــا بــن احلــن واآلخــر لزيــارة والدتــه وأوالده‪..‬‬\n‫ورأى العمــدة التواصــل مــع شــرطة منطقــة (القصيــم)؛ للتأكــد مــن‬\n‫صحــة مــا ذكــر‪ ..‬ثــم جــرت الكتابــة منــا ملديــر شــرطة (القصيــم) برقــم‬\n‫‪ 3367107‬يف ‪1433/1/10‬ه ـ لإلفــادة عــن صحــة مــا ذكــره املدعــى‬\n‫عليــه؛ أنــه يقيــم يف (بريــدة) حــي ‪ ....‬فــورد اجلــواب مــن مديــر شــرطة‬\n‫منطقــة (القصيــم) برقــم ‪ 14/2359131‬يف ‪1433/2/3‬ه ـ وتضمــن أن‬\n‫املذكــور لديــه منــزل بحــي ‪ ...‬بـ(بريــدة)‪ ،‬لكنــه غيــر موجــود بــه؛ حيــث‬\n‫إنــه مطلــوب لدينــا يف قضيــة حقوقيــة ولــم نتمكــن مــن العثــور عليــه‪،‬‬\n‫وهــو ال يوجــد يف هــذا الســكن‪ ،‬وحســب مــا توافــر لدينــا مــن معلومــات‬\n‫أنــه ميتلــك ســك ًنا يف املدينــة‪ ،‬ولــه عــدة مــزارع يف منطقــة (القصيــم)‬\n‫يظهــر فيهــا؛ أي أنــه ليــس لــه مقــر ثابــت ا‪.‬هــ‪ .‬وأدعــى األول قائـ ًـا‪ :‬يف‬\n\n\n                                                                                    ‫‪124‬‬\n\f      ‫ـزءا مــن قطعــة‬‫‪1430/11/1‬ه ـ اشــترت موكلتــي مــن املدعــى عليــه جـ ً‬\n      ‫األرض التــي ميتلكهــا ورقمهــا ‪ 1532‬مــن املُخطــط الذي ميلكه الكائن‬\n      ‫بحــي ‪ ...‬اشــترته منــه مببلــغ ســتمائة ألــف ريــال‪ ،‬وأطلــب إثبــات هــذا‬\n      ‫البيــع وحــدود هــذا اجلــزء الــذي اشــترته منــه موكلتــي هــي‪ :‬شــرقً ا شــارع‬\n                        ‫وغربــا شــارع بعــرض ‪ 24‬متـ ًـرا‪ ،‬وشـ ً‬\n      ‫ـمال القطعــة رقــم‬                                      ‫ً‬       ‫بعــرض ‪ 100‬متــر‪،‬‬\n      ‫وجنوبــا القطعــة رقــم ‪ ،1534‬ليبلــغ مجمــوع مســاحة مــا اشــترته‬   ‫ً‬       ‫‪،1530‬‬\n      ‫منــه ‪ 1100‬متــر مربــع‪ ..‬وبســؤال املدعــى عليــه أجــاب بقولــه‪ :‬مــا ذكــره‬\n      ‫املدعــي غيــر صحيــح‪ ،‬والصحيــح أن موكلــي ميتلــك هــذا املخطــط‬\n      ‫والقطعــة املذكــورة‪ ،‬وألن هــذه القطعــة علــى حــد حــرم املدينــة وحتتــاج‬\n      ‫إلــى مراجعــة وتخليــص لــدى أمانــة املدينــة فقــد اتفــق موكلــي مــع أخــي‬\n      ‫املدعيــة ‪ ...‬علــى أن يقــوم ‪ ...‬مبراجعــة معاملــة القطعــة لــدى األمانــة‪،‬‬\n      ‫ـاعا‪ ،‬ويدفــع كذلــك ملوكلــي‬     ‫وإذا انتهــت فلــه نصــف هــذه القطعــة مشـ ً‬\n      ‫أمــا‬\n         ‫ســتمائة ألــف ريــال دفــع منهــا ‪ ...‬ملوكلــي خمســمائة ألــف ريــال‪َّ ،‬‬\n      ‫فيدفــع كرســوم لــدى األمانــة‪ ،‬ثــم طلــب ‪...‬‬    ‫الباقــي ال ـ ‪ 100‬ألــف ريــال ُ‬\n      ‫أن يفــرغ هــذا اجلــزء باســم أختــه ‪ ...‬إال أن ‪ ...‬لــم يقــم بتخليــص املعاملــة‪،‬‬\n      ‫وحســب مــا علمتمــوه مــن األمانــة ال ميكــن إفراغهــا‪ ..‬وبطلــب البينــة‬\n      ‫مــن املدعــي‪ ،‬أبــرز العقــد املــؤرخ يف ‪1430/11/1‬ه ـ وتضمــن أن ‪ ...‬بــاع‬\n      ‫‪ ...‬مســاحة ألــف ومائــة متــر مــن قطعــة األرض رقــم ‪ 1532‬بحــي امللــك‬\n      ‫فهــد رقــم املخطــط ‪ 981‬م م يف ‪1425/5/1‬ه ـ اململــوك بالصــك رقــم‬\n      ‫‪ 2/4/15‬يف ‪1415/2/2‬ه ـ الصــادر عــن كتابــة عــدل املدينــة مببلــغ‬\n      ‫ســتمائة ألــف ريــال‪ ..‬توقيــع البائــع‪ ..‬توقيــع املشــترية‪ ...‬شــاهد‪ ...‬توقيعــه‬\n                                                                 ‫شــاهد ‪ ...‬توقيعــه ا‪.‬هــ‪.‬‬\n      ‫ـدي أنــا ‪ ...‬القاضــي باحملكمــة العامــة‬\n                                               ‫ويف يــوم الثالثــاء ‪1434/6/6‬ه ـ لـ ّ‬\n\n‫‪125‬‬\n\f‫باملدينــة املنــورة وخلــف فضيلــة الشــيخ ‪ ...‬حضــر املدعــي وكالــة ‪......‬‬\n‫كمــا حضــر املدعــى عليــه وكال ـ ًة ‪ ...‬ثــم جــرت تــاوة مــا مت ضبطــه‬\n‫ـاء علــى املــادة ‪166‬‬ ‫يف اجللســات الســابقة‪ ،‬فصــادق الطرفــان عليــه بنـ ً‬\n‫مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة‪ ..‬وأفــاد املدعــى عليــه‬\n  ‫بالوكالــة بــأن موكلــه يســكن منطقــة القصيــم حيــث ميتلــك منـ ً‬\n‫ـزل‬\n‫ـكنيا يف (بريــدة) بحــي ‪ ...‬ومزرعــة علــى طريــق ســاق مــن ضواحــي‬    ‫ًّ‬    ‫سـ‬\n‫بلــدة ‪ ...‬وأرغــب يف إقامــة الدعــوى يف محــل ســكن موكلــي املدعــى‬\n‫عليــه حســب النظــام؛ هكــذا قــرر‪ ..‬ثــم قــرر وكيــل املدعيــة قائـ ًـا‪:‬‬\n‫غيــر صحيــح‪ ،‬فاملدعــى عليــه يســكن يف (املدينــة املنــورة) وال يســكن‬\n‫يف (القصيــم) وأرغــب يف نظــر دعــوى موكلتــي يف محكمــة املدينــة‬\n‫املنــورة؛ هكــذا قــرر‪ ..‬ثــم أبــرز وكيــل املدعــى عليــه ورقــة‪ ،‬هــذا نصهــا‪:‬‬\n‫(اململكــة العربيــة الســعودية ـ وزارة الداخليــة ـ األمــن العــام‪ ،‬تعريــف‬\n‫لغــرض محكمــة املدينــة املنــورة‪ ،‬طا ِلــب التعريف االســم الرباعي ‪...‬رقم‬\n‫الهويــة ‪ ...‬مصــدر الهويــة‪ :‬املدينــة املنــورة‪ ،‬اجلنســية‪ :‬ســعودي العنــوان‪:‬‬\n‫حــي ‪ ...‬رقــم الهاتــف ‪ ...‬إلــى مــن يهمــه األمــر محكمــة املدينــة املنــورة‪،‬‬\n‫الســام عليكــم ورحمــة اهلل وبركاتــه‪ ..‬إن املوضــح اســمه وهويتــه‬\n‫ـدي وأثبتــت هــذه املعلومــات يف ســجل التعاريــف يف‬    ‫بأعــاه معــروف لـ َّ‬\n‫‪1431/5/28‬ه ـ ويســكن بحــي ‪ ...‬واهلل املوفــق‪ ..‬عمــدة حــي ‪ ...‬التاريــخ‬\n‫‪1431/5/28‬ه ـ ‪ ..‬التوقيــع ختــم العمــدة الرســمي‪ ،‬نصــادق علــى صحــة‬\n‫ختــم وتوقيــع العمــدة مديــر مركــز شــرطة (بريــدة) الشــمالي‪ ..‬توقيعــه‬\n‫‪1431/5/28‬ه ـ اخلتــم الرســمي‪ ..‬ا‪.‬هــ‪ ..‬وبعرضــه علــى وكيــل املدعيــة‬\n‫أجــاب قائـ ًـا‪ :‬ميكــن أنــه يســكن حــي ‪ ...‬ولكنــه غيــر موجــود يف‬\n‫القصيــم حقيقـ ًة؛ ألنــه متهــرب‪ ..‬وكــون لــه عقــارات يف القصيــم ال يــدل‬\n\n\n                                                                                     ‫‪126‬‬\n\f      ‫علــى أنــه يســكن بهــا هــذا جوابــي‪ .‬كمــا أبــرز وكيــل املدعــى عليــه‬\n      ‫ورقــة ثانيــة‪ ،‬هــذا نصهــا‪( :‬بســم اهلل الرحمــن الرحيــم‪1434/4/15 ،‬ه ـ‬\n      ‫نشــهد نحــن املوقعــن أســماءنا أدنــاه ‪ ...‬بطاقــة أحــوال رقــم ‪ ...‬و‪ ...‬بطاقــة‬\n      ‫أحــوال رقــم ‪ ...‬بــأن األخ ‪ ...‬بطاقــة رقــم ‪ ...‬مــن ســكان منطقــة (القصيــم)‬\n      ‫يف مزرعتــه الكائنــة علــى طريــق ‪ ...‬مــن ضواحــي بلــدة ‪ ...‬واملزرعــة‬\n      ‫مملوكــة لــه بصكــوك شــرعية باســمه ولطلبــه منــا إثبــات ذلــك شــهدنا‬\n      ‫مبــا علمنــا‪ ،‬واهلل املوفــق‪ ..‬شــاهد ‪ ...‬توقيعــه شــاهد ‪ ...‬توقيعــه‪ ..‬نصــادق‬\n      ‫علــى معرفــة الشــهود‪ :‬عمــدة مركــز ‪ .........‬توقيعــه اخلتــم الرســمي)‬\n      ‫ا‪.‬هــ‪ ..‬وبعرضــه علــى وكيــل املدعيــة أجــاب قائـ ًـا‪ :‬ميكــن أن يكــون لــه‬\n      ‫عقــارات يف القصيــم وهــو ال يســكن فيهــا؛ هــذا جوابــي‪ ..‬ثــم إنــه وبعــد‬\n      ‫التأمــل يف القضيــة وحيــث إن وكيــل املدعــى عليــه ُمصــر علــى ســماع‬\n      ‫الدعــوى يف مقــر ســكن املدعــى عليــه منــذ أول جلســة ويدفــع بذلــك‪،‬‬\n      ‫وحيــث إنــه أحضــر مــا يثبــت بــأن موكلــه يســكن حــي ‪ ...‬بـ(بريــدة) مــن‬\n      ‫عمــدة حــي ‪ ...‬وكذلــك ميتلــك مزرعــة يف القصيــم ضواحــي ‪ ...‬طريــق ‪...‬‬\n      ‫وبعــد االطــاع علــى املــادة العاشــرة واملــادة الرابعــة والثالثــن مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحــه التنفيذيــة؛ لذلــك فقــد قــررت صــرف‬\n      ‫النظــر عــن دعــوى املدعيــة باألصالــة‪ ،‬وأفهمــت وكيلهــا بــأن لهــا حــق‬\n      ‫إقامــة الدعــوى يف احملكمــة التــي يقــع يف نطــاق اختصاصهــا محــل‬\n      ‫إقامــة املدعــى عليــه باألصالــة‪ ،‬وبذلــك حكمــت وقنــع وكيــل املدعــى‬\n      ‫عليــه باحلكــم ولــم يقتنــع وكيــل املدعيــة‪ ،‬وطلــب محكمــة االســتئناف‬\n      ‫مبوجــب الئحــة اعتراضيــة فأجيــب لطلبــه‪ ،‬و ُأفهــم بــأن لــه مهلــة ثالثــن‬\n      ‫يومــا لتقــدمي الالئحــة االعتراضيــة مــن تاريــخ ‪1434/6/10‬ه ـ وهو موعد‬        ‫ً‬\n      ‫تسـلُّم صــورة الصــك‪ ،‬وإذا تأخــر فيكتســب احلكــم القطعيــة ويســقط‬\n\n\n‫‪127‬‬\n\f‫حقــه يف طلــب االســتئناف ففهــم ذلــك‪ ..‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف ‪1434/06/06‬هــ‪.‬‬\n‫احلمد هلل وحده وبعد‪ ،‬ويف يوم االثنني ‪1434/6/12‬هـ فتحت اجللســة‬\n‫صباحــا‪ ،‬وفيهــا حضــر وكيــل‬ ‫ً‬        ‫يف الســاعة العاشــرة وعشــرين دقيقــة‬\n‫املدعيــة ‪ ...‬وقــرر قناعتــه باحلكــم وطلــب عــدم رفــع املعاملــة حملكمــة‬\n‫االســتئناف وطلــب رصــد ذلــك بضبــط القضيــة وإحالتهــا إلــى محكمــة‬\n‫(بريــدة) ف ُأجيــب لطلبــه‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                      ‫وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف ‪1434/6/12‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬فقــد جــرى بعــث املعاملــة لفضيلــة رئيــس‬\n‫احملكمــة العامــة بـ(بريــدة) بخطابنــا رقــم ‪ 34/1532626‬وتاريــخ‬\n‫‪1434/6/18‬ه ـ حســب االختصــاص‪ .‬فوردنــا جــواب فضيلتــه رقــم‬\n‫‪ 34/1532626‬بتاريــخ ‪1434/7/11‬ه ـ لعــدم االختصــاص‪ ..‬وحيــث‬\n‫إن حكمــي أعــاه واجــب االســتئناف مبوجــب املــادة ‪ 2/74‬مــن نظــام‬\n‫املرافعــات الشــرعية ولوائحــه التنفيذيــة ـ ـ لــذا أمــرت برفعــه ومرفقاتــه‬\n‫حملكمــة االســتئناف مبكــة املكرمــة للفصــل يف ذلــك‪ ،‬واهلل املوفــق‪،‬‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ُ .‬حــرر يف‬\n                                                                 ‫‪1434/9/7‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد‪ ،‬فقــد ُأعيــدت إلينــا املعاملــة مــن محكمــة‬\n‫مرفقــا معهــا القــرار الصــادر عــن الدائــرة‬\n                                           ‫ً‬      ‫االســتئناف مبكــة املكرمــة‬\n‫احلقوقيــة اخلامســة برقــم ‪ 34329182‬وتاريــخ ‪1434/10/13‬ه ـ املرفــق‬\n‫باملعاملــة‪ ،‬واملظهــر علــى الصــك املتضمــن املوافقــة علــى احلكــم‬\n‫باألكثريــة بصــرف النظــر عــن الدعــوى لعــدم االختصــاص‪ ..‬قاضــي‬\n                                         ‫لــذا جــرى إحلاقــه ‪ ،‬وبــاهلل التوفيــق‪.‬‬\n                                                      ‫ُحرر يف ‪1434/10/27‬هـ‪.‬‬\n                                                                                      ‫‪128‬‬\n\f      ‫احلمــد هلل وحــده ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ نحــن‬\n      ‫قضــا َة االســتئناف بالدائــرة احلقوقيــة اخلامســة يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة جــرى م ّنــا االطــا ُع علــى هــذا احلكــم الصــادر‬\n      ‫مــن فضيلــة الشــيخ ‪...‬القاضــي باحملكمــة العامــة باملدينــة املنــورة‬\n      ‫املســجل بعــدد ‪ 34233355‬وتاريــخ ‪1434/06/06‬ه ـ املتضمــن دعــوى‬\n      ‫‪ ...‬ضــد ‪...‬احملكــوم في ــه مبــا دون باطــن الصــك ‪ ،‬وبدراســة احلكــم‬\n      ‫وص ــورة ضبط ــه تق ــرر باألكثريــة املوافق ــة عل ــى احلكــم بصــرف النظر‬\n      ‫عــن الدعــوى لعــدم االختصــاص وبــاهلل التوفيــق وصل ــى اهلل عل ــى نبينــا‬\n                                                 ‫محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪129‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":122,"source_page_end":129,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3fa2ace90b