       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"871571cf-e9ff-5cbd-9531-8a2140bd99c7","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -تداخل أراضي -أساس ملكية األرض منحة -املختص بنظر النزاعات الناشئة عن توزيع األراضي جلنة مش كلة من ممثلن عن وزارة الزراعة والعدل والداخلية واملياه والكهرباء - احلكم بصرف النظر عن الدعوى لعدم االختصاص .","document_number":"3410054","case_number":"33655933","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/12","year":"1434","subject":"اختصاص -تداخل أراضي -أساس ملكية األرض منحة -املختص بنظر النزاعات الناشئة عن توزيع األراضي جلنة مش كلة من ممثلن عن وزارة الزراعة والعدل والداخلية واملياه والكهرباء - احلكم بصرف النظر عن الدعوى لعدم االختصاص .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3410054 :‬تاريخه‪1434/1/12 :‬هـ‬\n                  ‫رقم الدعوى‪33655933 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34256751‬تاريخه‪1434/7/2 :‬هـ‬\n\n\n‫اختصــاص ‪ -‬تداخــل أراضــي ‪ -‬أســاس ملكيــة األرض منحــة ‪ -‬املختــص‬\n‫بنظــر النزاعــات الناشــئة عــن توزيــع األراضــي جلنــة مشـ ّـكلة مــن‬\n‫ممثلــن عــن وزارة الزراعــة والعــدل والداخليــة وامليــاه والكهربــاء ‪-‬‬\n             ‫احلكــم بصــرف النظــر عــن الدعــوى لعــدم االختصــاص ‪.‬‬\n\n\n\n\n                    ‫‪ .1‬املادة العاشرة من نظام توزيع األراضي البور ‪.‬‬\n       ‫‪ .2‬تعميم معالي وزير العدل رقم ‪/13‬ت‪ 2254/‬يف ‪1424/6/4‬هـ ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه وكالــة بأنــه وضــع يــده علــى‬\n‫جــزء مــن أرضــه وطلــب رفــع يــده عــن هــذه األرض ‪،‬واألرض املدعــى‬\n‫بهــا أرض زراعيــة آلــت للمدعــي وللمدعــى عليــه مبوجــب نظــام توزيــع‬\n‫األراضــي البــور ‪،‬وبنــاء علــى املــادة العاشــرة املعدلــة مــن نظــام توزيــع‬\n‫األرضــي البــور والتــي جعلــت االختصــاص بنظــر املنازعــات الناشــئة عــن‬\n‫تطبيــق أحــكام هــذا النظــام للجنــة أوضحــت تشــكيلها هــذه املــادة‪،‬‬\n‫علــى أنــه يجــوز التظلــم مــن قــرارات هــذه اللجنــة أمــام ديــوان املظالــم‬\n‫خــال ســتني يوم ـ ًا مــن تاريــخ اإلبــاغ بالقــرار‪ ،‬وجــرى إفهــام طــريف‬\n‫القضيــة بعــدم اختصــاص هــذه احملكمــة بنظــر هــذه القضيــة وأنهــا مــن‬\n\n                                                                                    ‫‪46‬‬\n\f     ‫ـكلة بأمــر املقــام الســامي املشــار إليــه يف تعميــم‬\n                                                           ‫اختصــاص اللجنــة املشـ ّ‬\n     ‫معالــي وزيــر العــدل ‪ ،‬لــذا قضــت احملكمــة بصــرف النظــر عــن الدعــوى‬\n     ‫لعــدم االختصــاص وقنــع املدعــى عليــه واعترض املدعــي بالئحة‪،‬وصدق‬\n     ‫احلكــم مــن الدائــرة احلقوقيــة األولــى مبحكمــة االســتئناف مبنطقــة‬\n                                                                              ‫حائــل ‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة العامــة‬\n     ‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بحائل‪/‬املســاعد برقــم ‪ 33655933‬وتاريــخ ‪1433/11/15‬ه ـ‬\n     ‫املقيــدة باحملكمــة برقــم ‪ 331923832‬وتاريــخ ‪ 1433/11/01‬ه ـ‬\n     ‫ففــي يــوم االثنــن املوافــق ‪ 1433/11/29‬ه ـ افتتحــت اجللســة الســاعة‬\n     ‫‪ 8 : 33‬بشــأن دعــوى ‪ .........‬ســجل مدنــي رقــم ‪.........‬ضــد ‪.........‬بشــأن‬\n     ‫تداخــل صكــوك والتــي حتــدد للقضيــة موعــدا هــذا اليــوم الســاعة‬\n     ‫‪ 8 : 00‬عليــه لــم يحضــر املدعــي وال املدعــى عليــه وال مــن ميثلهمــا ولــم‬\n     ‫يقدمــا عــذرا لــذا قــررت شــطب القضيــة للمــرة األولــى ورفعــت اجللســة‬\n     ‫يف الســاعة ‪ 8 : 37‬وعليــه حصــل التوقيــع احلمــد هلل وحــده وبعــد ويف‬\n     ‫يــوم االثنــن املوافــق ‪1434/1/12‬ه ـ افتتحــت اجللســة يف الســاعة ‪29‬‬\n     ‫‪ 10 :‬وفيهــا حضــر ‪.........‬ســعودي بالســجل املدنــي رقــم ‪.........‬بصفتــه‬\n     ‫ا عــن ‪.........‬وبســؤاله عــن الوكالــة قــال أن صورتهــا يف املعاملــة‬‫وكي ـ ً‬\n     ‫وباالطــاع علــى صورتهــا يف املعاملــة وجدتهــا تتضمــن انــه وكيــا عــن‬\n     ‫‪.........‬مبوجــب صــورة الوكالــة الصــادرة مــن كتابــة عــدل حائــل الثانيــة‬\n     ‫برقــم ‪ 8988‬وتاريــخ ‪1431/3/24‬ه ـ اجللــد ‪ 2528‬واملخــول لــه فيهــا‬\n\n‫‪47‬‬\n\f‫يف بيــع االرض الزراعيــة اخلاصــة بــي ذات الرقــم ‪ 169 - 168‬الواقعــة‬\n‫بالقاعــد باملخطــط رقــم ‪ 100‬واململوكــة لــي بالصــك رقــم ‪470-17‬‬\n‫تاريــخ ‪1426/4/6‬ه ـ الصــادر مــن كتابــة عــدل حائــل األولــى واإلفــراغ‬\n‫للمشــتري واســتالم القيمــة بشــيكات مصدقــة بإســمي ومراجعــة فــرع‬\n‫وزارة الزراعــة والبنــك ‪.........‬وكتابــة العــدل األولــى كمــا لــه حــق‬\n‫تخطيــط األرض وفرزهــا وجتزئتهــا بصكــوك مســتقلة واســتالمها‬\n‫وبيعهــا ومراجعــة جميــع الدوائــر احلكوميــة الالزمــة لذلــك وانهــاء‬\n‫كافــة االجــراءات املتعلقــة بذلــك ولــه حــق توكيــل الغيــر والتوقيــع نيابــة‬\n‫عنــي مبــا ذكــر وحضــر حلضــوره ‪.........‬ســعودي بالســجل املدنــي رقــم‬\n‫ا عــن ‪.........‬وقــدم صــورة وكالــة صــادرة مــن‬    ‫‪.........‬وقــال إننــي وكي ـ ً‬\n‫كتابــة عــدل حائــل الثانيــة برقــم ‪ 29144‬وتاريــخ ‪1432/9/8‬ه ـ جلــد‬\n‫‪ 3079‬ثــم جــرى إفهــام املدعــي وكالــة بأنــه البــد مــن إحضــار اصــل‬\n‫وكالــة تخولــه إقامــة الدعــوى واملرافعــة واملدافعــة حتــى نتمكــن مــن‬\n‫ســماع دعــواه فقــال أننــي ال أســتطيع حيــث أن موكلــي مريض ـ ًا ومنــوم‬\n‫يف املستشــفى وهــذه الوكالــة ســبق أن قبلهــا ديــوان املظالــم لــذا فقــد‬\n‫صرفــت النظــر عــن دعــواه لعــدم تخويلــه بإقامــة الدعــوى وبــه حكمــت‬\n‫وبإعــان احلكــم قــرر عــدم القناعــة واســتعد بتقــدمي الئحــة اعتراضيــة‬\n‫فأفهــم بــأن عليــه املراجعــة غــد ًا الثالثــاء املوافــق ‪1434/1/13‬ه ـ‬\n‫الســاعة ‪ 11 : 30‬الســتالم صــورة الصــك وتقــدمي اعتراضــه عليــه خــال‬\n‫مــدة قدرهــا ثالثــون يومــا تبــدأ مــن تاريــخ اســتالمه يف ‪1434/1/13‬ه ـ‬\n‫واذا مضــت املــدة ولــم يقــدم اعتراضــه خاللهــا فــإن احلكــم يكتســب‬\n‫القطعيــة ففهــم ذلــك ورفعــت اجللســة يف الســاعة ‪ 10 : 37‬وعليــه حصــل‬\n‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه اجمعــن‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫حــرر يف ‪1434/1/12‬ه ـ احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق‬\n     ‫‪1434/2/3‬ه ـ افتتحــت اجللســة يف الســاعة ‪ 11 : 00‬وحضــر املدعــي‬\n     ‫وكالــة كمــا حضــر ‪.........‬ســعودي بالســجل املدنــي رقــم ‪.........‬الوكيــل‬\n     ‫عــن ‪.........‬ســعودي بالســجل املدنــي رقــم ‪.........‬مبوجــب الوكالــة‬\n     ‫الصــادرة مــن كتابــة عــدل حائــل الثانيــة برقــم ‪ 2524‬يف ‪1434/1/20‬هـ‬\n     ‫اجللــد ‪ 3676‬وقــال املدعــي وكالــة إننــي قانــع باحلكــم الســابق وقــد‬\n     ‫أحضــرت وكالــة فوجدتهــا متضمنــه توكيلــه مــن قبــل املدعــي اصالــة‬\n     ‫يف مراجعــة كافــة الدوائــر احلكوميــة الشــرعية واإلداريــة واحملاكــم‬\n     ‫بخصــوص رفــع الدعــوى ضــد فــرع وزارة التجــارة بحائــل أو أي جهــة‬\n     ‫أخــرى لهــا عالقــة بالقضيــة التــي يــود املدعــي اصالــة رفعهــا بخصــوص‬\n     ‫قطعتــي األرض رقــم ‪ 168‬ورقــم ‪ 169‬واململوكتــان للمدعــي أصالــة‬\n     ‫مبوجــب الصــك رقــم ‪ 87/470/17‬وتاريــخ ‪1426/4/6‬ه ـ الصــادرة مــن‬\n     ‫عــدل حائــل والواقعتــان يف مخطــط رقــم ‪ 100‬غــرب القاعــد بحائــل ولــه‬\n     ‫احلــق يف إقامــة الدعــوى وحضــور اجللســات واملدافعــة واملرافعــة واجلــرح‬\n     ‫والتعديــل واإلقــرار و اإلنــكار وإحضــار الشــهود وتقــدمي البينــات وطلــب‬\n     ‫اليمــن وردهــا وقبولهــا والصلــح والتنــازل وســماع احلكــم وقبولــه ونفيــه‬\n     ‫واالســتالم والتســليم وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n     ‫عــدل املدينــة املنــورة الثانيــة برقــم ‪ 41937‬يف ‪1432/7/5‬ه ـ اجللــد ‪7117‬‬\n     ‫وحــرر املدعــي دعــواه قائــا إن مــن اجلــاري يف ملــك موكلــي وحتــت‬\n     ‫تصرفــه قطعتــي األرض رقــم ‪ 168‬ورقــم ‪ 169‬واململوكتــان للمدعــي‬\n     ‫أصالــة مبوجــب الصــك رقــم ‪ 87/470/17‬وتاريــخ ‪1426/4/6‬ه ـ‬\n     ‫الصــادرة مــن عــدل حائــل والواقعتــان يف مخطــط رقــم ‪ 100‬غــرب‬\n     ‫القاعــد بحائــل واحملــدودة شــما ًال شــارع وجنوبــا شــارع وشــرقا قطعــة‬\n\n\n‫‪49‬‬\n\f‫رقــم ‪ 167‬وغرب ـ ًا رأس مثلــث وهــذا العقــار مــن ضمــن مخطــط زراعــي‬\n‫معتمــد مت توزيعــه مبوجــب نظــام األراضــي البــور وقــد قــام املدعــى‬\n‫عليــه أصالــة وهــو يحدنــا مــن جهــة الشــمال بتخطيــط ملكــه الزراعــي‬\n‫وقســمه إلــى عشــرين قطعــة وقــد اســتدخل جــزء مــن ملــك موكلــي مــن‬\n‫جهــة الشــمال يف املخطــط الزراعــي الــذي يخصــه ولــذا فإنــي أطلــب رفع‬\n‫يــد املدعــى عليــه أصالــة مــن ملــك موكلــي هــذه دعــواي وجــرى ســؤال‬\n‫املدعــى عليــه عــن ملــك موكلــه فقــال إن املدعــى عليــه أصالــة يحــد‬\n‫موكلــي مــن اجلهــة اجلنوبيــة الشــرقية وموكلــي ميلــك أرضــه الزراعيــة‬\n‫رقــم ‪ 91‬الواقعــة يف ‪ 37‬كــم شــمال حائــل اململوكــه مبوجــب الصــك‬\n‫الصــادر مــن كتابــة عــدل حائــل برقــم ‪ 320/28‬يف ‪1419/8/23‬ه ـ‬\n‫واســاس امللــك مت منحــه ل‪ .........‬مبوجــب نظــام توزيــع األراضــي البــور‬\n‫ثــم آل إلــى موكلــي بالشــراء وبعــد ســماع الدعــوى واإلجابــة وجــد‬\n‫ا‬‫أن املدعــي يطالــب املدعــى عليــه حســب مــا جــاء يف دعــواه تفصي ـ ً‬\n‫بخصــوص أرض زراعيــة صــادرة مــن وزارة الزراعــة املبنــي علــى قــرار‬\n‫توزيــع أرض زراعيــة مبوجــب نظــام توزيــع األراضــي البــور بنــاء علــى‬\n‫قــرار التمليــك رقــم ‪ 14973‬يف ‪1425/3/8‬ه ـ واملصــادق عليــه مــن املقــام‬\n‫الســامي رقــم ‪/107/4‬م يف ‪1425/3/17‬ه ـ وقــرار التوزيــع رقــم ‪34234‬‬\n‫يف ‪1409/5/19‬ه ـ واملشــار إليــه يف الصــك الصــادر مــن كتابــة العــدل‬\n‫وهــذا اخلــاف نــاجت مــن التطبيــق وقــد ســبق أن تلقــت احملكمــة تعميــم‬\n‫معالــي وزيــر العــدل رقــم ‪/13‬ت‪ 2254/‬وتاريــخ ‪1424/6/4‬ه ـ ونصــه‬\n‫( تعميــم قضائــي علــى كافــة احملاكــم و كتابــات العــدل الســام‬\n‫عليكــم ورحمــة اهلل وبركاتــه وبعــد لقــد تلقينــا نســخة مــن برقيــة‬\n‫صاحــب الســمو امللكــي رئيــس ديــوان رئاســة مجلــس الــوزراء رقــم‬\n‫‪ 12148‬وتاريــخ ‪1424/3/13‬ه ـ ومشــفوعها ‪ -1‬نســخة مــن قــرار مجلس‬\n                                                                                ‫‪50‬‬\n\f     ‫الــوزراء املوقــر رقــم (‪ )37‬وتاريــخ ‪1424/2/12‬ه ـ القاضــي بتعديــل املادة‬\n     ‫(العاشــرة) مــن نظــام توزيــع األراضــي البــور الصــادر باملرســوم امللكــي‬\n     ‫رقــم (م‪ )66/‬وتاريــخ ‪1388/7/6‬ه ـ لتكــون بالنــص اآلتــي ( تشــكيل‬\n     ‫جلنــة يف وزارة الزراعــة مــن ممثلــن لهــذه الــوزارة ووزارة العــدل ووزارة‬\n     ‫الداخليــة ووزارة امليــاه والكهربــاء يكــون أحدهــم مستشــار ًا نظامي ـ ًا‬\n     ‫للنظــر يف جميــع املنازعــات الناشــئة عــن تطبيــق أحــكام هــذا النظــام‬\n     ‫وتعتمــد قــرارات هــذه اللجنــة مــن وزيــر الزراعــة ويجــوز ملــن صــدر ضــده‬\n     ‫قــرار مــن هــذه اللجنــة التظلــم منــه أمــام ديــوان املظالــم خــال ســنني‬\n     ‫يومـ ًا مــن تاريــخ إبالغــه بالقــرار ) ‪ -2‬نســخة مــن املرســوم امللكــي رقــم‬\n     ‫(م‪ )10/‬وتاريــخ ‪1424/3/10‬ه ـ الصــادر باملرافقــة علــى ذلــك ‪ ...‬الــخ‬\n     ‫لــذا نرغــب أليكــم االطــاع واعتمــاد موجبــه وجتــدون برفقــه صــور ًا‬\n     ‫ممــا أشــير إليــه واهلل يحفظكــم وزيــر العــدل ‪ ).........‬أ ‪ .‬ه ـ لــذا أفهمــت‬\n     ‫طــريف القضيــة بعــدم اختصــاص هــذه احملكمــة بنظــر هــذه القضيــة‬\n     ‫وأنهــا مــن اختصــاص اللجنــة املشــكلة بأمــر املقــام الســامي املشــار‬\n     ‫إليــه يف تعميــم معالــي وزيــر العــدل وصرفــت النظــر عــن الدعــوى لعــدم‬\n     ‫االختصــاص وبــه حكمــت وبإعــان احلكــم قنــع بــه املدعــى عليــه‬\n     ‫وكالــة أمــا املدعــي وكالــة فقــرر عــدم القناعــة واســتعد بتقــدمي الئحــة‬\n     ‫فأفهــم بــأن عليــه املراجعــة يــوم الســبت املوافــق ‪1434/2/9‬ه ـ الســاعة‬\n     ‫الواحــدة ظهــر ًا الســتالم صــورة الصــك ولــه حــق املعارضــة خــال مــدة‬\n     ‫قدرهــا ثالثــون يومـ ًا مــن تاريــخ ‪1434/2/9‬ه ـ اذا مضــت املــدة ولــم يقــدم‬\n     ‫اعتراضــه خاللهــا فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم‬\n     ‫القطعيــة ورفعــت اجللســة يف الســاعة ‪ 11 : 10‬وعليــه حصــل التوقيــع‬\n                  ‫وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه اجمعــن ‪.‬‬\n                                                                               ‫•ص‬\n\n‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":46,"source_page_end":51,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5a4d0a605c9adc6236e7f811190120b343cd36f93f77ae5084c1511ecb3c14cc","normalized_text_hash":"18becc2f0529d2024c677e5c3a254530351cb43081859c56c8827c03e8257d68","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p46-3410054"},{"id":"b0344aa2-6c8d-534a-8288-ffd634e9fccd","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -التلفظ على رجل األمن وتهديده -عدم اختصاص المحكمة بقضايا االعتداء على رجل األمن أثناء عمله -اختصاص ديوان املظالم بنظر هذه القضايا - 1املادة السابعة والثامنة من نظام مكافحة الرشوة.","document_number":"3428954","case_number":"3426194","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بشرورة فلقد وردتنا املعاملة احملالة لنا ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/4","year":"1434","subject":"اختصاص -التلفظ على رجل األمن وتهديده -عدم اختصاص المحكمة بقضايا االعتداء على رجل األمن أثناء عمله -اختصاص ديوان املظالم بنظر هذه القضايا - 1املادة السابعة والثامنة من نظام مكافحة الرشوة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك‪ 3428954:‬تاريخه‪1434/2/4 :‬هـ‬\n                   ‫رقم الدعوى‪3426194 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34237829‬تاريخه‪1434/6/12 :‬هـ‬\n\n\n‫اختصــاص ‪ -‬التلفــظ علــى رجــل األمــن وتهديــده ‪ -‬عــدم اختصــاص‬\n‫احملكمــة بقضايــا االعتــداء علــى رجــل األمــن أثنــاء عملــه ‪ -‬اختصــاص‬\n                                     ‫ديــوان املظالــم بنظــر هــذه القضايــا‬\n\n\n\n\n              ‫‪ - 1‬املادة السابعة والثامنة من نظام مكافحة الرشوة‪.‬‬\n      ‫‪ - 2‬قرار جلنة تنازع االختصاص رقم ‪/147‬ت يف ‪1431/12/23‬هـ‬\n\n\n\n\n‫اتهــام املدعــي العــام للمدعــى عليــه األول بقيامــه بالتلفــظ علــى رجــل‬\n‫األمــن وتهديــده وللمدعــى عليــه الثانــي بتهديــد رجــل األمــن ‪ ،‬يطلــب‬\n‫إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة زاجــرة لهمــا‬\n‫ورادعــة لغيرهمــا ‪،‬وقــد أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ‪،‬لكــن‬\n‫مت احلكــم بصــرف النظــر عــن الدعــوى لعــدم االختصــاص ‪،‬و قــرر‬\n‫املدعــي العــام االعتــراض وطلــب االســتئناف بالئحــة وقــرر املدعــى عليــه‬\n                   ‫القناعــة ‪ ،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                   ‫‪52‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬رئيــس احملكمــة العامــة بشــرورة‬\n     ‫فلقــد وردتنــا املعاملــة احملالــة لنــا برقــم ‪ 3426194‬الــواردة مــن دائــرة‬\n     ‫التحقيــق واالدعــاء العــام بشــرورة وبرفقهــا الئحــة الدعــوى العامــة مــن‬\n     ‫املدعــي العــام‪ ..........‬وادعــى فيهــا قائــا بصفتــي مدعيــا عامــا بدائــرة‬\n     ‫التحقيــق واالدعــاء العــام مبحافظــة شــرورة أدعــي علــى ‪...............-1 :‬‬\n     ‫يبلــغ مــن العمــر ‪27‬عــام ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم‬\n     ‫(‪ ).........‬متــزوج يقيــم بشــرورة املقبــوض عليــه بتاريــخ ‪1433/9/2‬ه ـ‬\n     ‫واملفــرج عنــه بالكفالــة احلضوريــة بتاريــخ ‪1433/9/3‬ه ـ اســتنادا للمــادة‬\n     ‫‪ 120‬مــن نظــام اإلجــراءات اجلزائيــة‪ ............-2.‬يبلــغ مــن العمــر ‪25‬عــام‬\n     ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ ).......‬متــزوج يقيــم‬\n     ‫بشــرورة املقبــوض عليــه بتاريــخ ‪1433/9/2‬ه ـ واملفــرج عنــه بالكفالــة‬\n     ‫احلضورية بتاريخ‪1433/9/3‬هـ استنادا للمادة ‪ 120‬من نظام اإلجراءات‬\n     ‫اجلزائيــة ‪.‬انــه بتاريــخ ‪1433/9/2‬ه ـ وأثنــاء قيــام أمــن الطــرق بالتفتيــش‬\n     ‫يف طريــق ‪ ......‬مت اســتيقاف ‪ .....‬موديــل ‪2012‬م وعنــد طلــب إثباتــات‬\n     ‫األشــخاص رفــض املرافــق املدعــى عليــه األول النــزول مــن املركبــة‬\n     ‫وقــام بالتلفــظ علــى رجــل األمــن بقولــه (يــا ورع بــدري عليــك تفتــش ‪) .....‬‬\n     ‫وقامــوا كال منهمــا بتهديــد رجــل األمــن بقولهــم (علــي الطــاق أتوطــأ‬\n     ‫يف بطنــك) و(أكســر ضروســك) حيــث هربــوا مــن النقطــة ملــدة عشــر‬\n     ‫دقائــق ثــم عــادوا للنقطــة وقامــوا بالتهديــد والتفحيــط ثــم مت القبــض‬\n     ‫عليهــم ‪.‬وباســتجواب املدعــى عليــه األول أفــاد بأنــه قــال للعســكري‬\n     ‫أنــت ال حتتــرم ‪ ...........‬وغطــي ســنونك ال تســتفزني ‪ .‬وباســتجواب‬\n\n‫‪53‬‬\n\f‫املدعــى عليــه الثانــي أفــاد بأنــه مســك يــد العســكري عندمــا أراد أن‬\n‫يطفــي ســيارته‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‬\n‫األول بالتلفــظ علــى رجــل األمــن بقوله(بــدري عليــك تفتــش ‪ ).....‬وقولــه‬\n‫(علــي الطــاق أتوطــأ يف بطنــك) وللمدعــى عليــه الثانــي بتهديــد رجــل‬\n‫األمــن بقولــه (علــي الطــاق أتوطــأ يف بطنــك وأكســر ضروســك)‬\n‫وذلــك لألدلــة والقرائــن التالية‪-1:‬مــا جــاء يف أقوالهمــا يف محضــر‬\n‫االســتجواب املرفــق لفــة رقــم(‪ -2 - )12‬مــا جــاء يف محضــر القبــض‬\n‫املنــوه عنــه واملرفــق لفــه رقــم (‪ -3 - )5‬مــا جــاء يف أقــوال الشــاهد يف‬\n‫محضــر االســتجواب املرفــق لفــه رقــم (‪ - .)12‬وبالبحــث عــن ســوابقهما‬\n‫لــم يعثــر لهمــا علــى ســوابق جنائيــة ‪ .‬وحيــث أن مــا أقــدم عليــه املدعــى‬\n‫عليهمــا وهمــا بكامــل أهليتهمــا املعتبــرة شــرعا فعــل محــرم ومعاقــب‬\n‫عليــه شــرعا أطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بعقوبــة‬\n‫تعزيريــة زاجــرة لهمــا ورادعــة لغيرهمــا‪ .‬وبعــرض الدعــوى علــى املدعــى‬\n‫عليــه األول‪ ..........‬واملدعــى عليــه الثانــي ‪ .........‬أجــاب املدعــى عليــه‬\n‫األول قائـ ًـا‪ :‬مــا ذكــره املدعــي العــام يف دعــواه بأننــي قمــت باملــرور‬\n‫علــى نقطــة التفتيــش يف طريــق ‪ ......‬وأننــي تلفظــت علــى رجــل األمــن‬\n‫بقولــي لــه (بــدري عليــك تفتــش ‪ ).....‬وأننــي قلــت لــه ( علــي الطــاق‬\n‫أتوطــأ يف بطنــك وأكســر ضروســك) فهــذا غيــر صحيــح والصحيــح‬\n‫أننــي وقفــت يف التفتيــش وطلــب إثباتــي أنــا واملدعــى عليــه الثانــي‬\n‫فأعطينــاه ولــم نتلفــظ علــى أحــد أبــدا كمــا ورد يف الدعــوى وأجــاب‬\n‫املدعــى عليــه الثانــي قائــا مــا ذكــره املدعــي العــام بأننــي كنــت مــع‬\n‫املدعــى عليــه األول يف الســيارة ووقفنــا يف التفتيــش علــى طريــق الوديعــة‬\n‫وأننــي قمــت بالتلفــظ علــى رجــل األمــن بقولــي (علــي الطــاق أتوطــأ يف‬\n\n\n                                                                                    ‫‪54‬‬\n\f     ‫بطنــك وأكســر ضروســك ) فهــذا غيــر صحيــح والصحيــح أننــا وقفنــا‬\n     ‫بالســيارة وكنــت أنــا الســائق وطلــب اإلثباتــات وأعطينــاه مــا طلــب وقــام‬\n     ‫بالدخــول للســيارة يريــد إطفــاء الســيارة ولــم نقــم بالتلفــظ علــى أحــد‬\n     ‫بنفــس األلفــاظ الــذي ذكرهــا املدعــي العــام يف الدعــوى هكــذا أجــاب‬\n     ‫وبدراســة املعاملــة والدعــوى تبــن أن دعــوى املدعــي العــام تتعلــق بالتلفــظ‬\n     ‫علــى رجــل األمــن أثنــاء مزاولتــه لعملــه ولقــد نصــت املــادة الســابعة مــن‬\n     ‫نظــام مكافحــة الرشــوة (يعاقــب بالعقوبــة املنصــوص عليهــا يف املــادة‬\n     ‫األولــى مــن هــذا النظــام مــن يســتعمل القــوة أو العنــف أو التهديــد يف حــق‬\n     ‫موظــف عــام ليحصــل منــه علــى قضــاء أمــر غيــر مشــروع أو ليحملــه علــى‬\n     ‫اجتنــاب أداء عمــل مــن األعمــال املكلــف بهــا ) وبينــت املــادة الثامنــة مــن‬\n     ‫نفــس النظــام أنــه ( يعــد يف حكــم املوظــف العــام يف تطبيــق أحــكام‬\n     ‫هــذا النظــام ‪-1‬كل مــن يعمــل لــدى الدولــة أو لــدى أحــد األجهــزة ذات‬\n     ‫الشــخصية املعنويــة العامة‪...‬الــخ) وحيــث أن تلفــظ املدعــى عليهــم علــى‬\n     ‫رجــل األمــن باأللفــاظ الــواردة يف الدعــوى عبــارة عــن تهديــد وحيــث أن‬\n     ‫املخــول بتطبيــق نظــام مكافحــة الرشــوة هــي احملكمــة اإلداريــة لــذا‬\n     ‫فقــد قــررت صــرف النظــر عــن الدعــوى لعــدم االختصــاص وأفهمــت‬\n     ‫املدعــي العــام بــأن عليــه إقامــة الدعــوى يف احملكمــة اإلداريــة يف مدينــة‬\n     ‫جنــران ومبــا تقــدم حكمــت وبعــرض احلكــم علــى املدعــى عليهمــا‬\n     ‫قــررا القناعــة وأمــا املدعــي العــام ‪........‬قــرر االعتــراض علــى احلكــم‬\n     ‫بنفــس الالئحــة وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                     ‫وســلم حــرر يف ‪1434/1/17‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/3/29‬ه ـ افتتحــت‬\n     ‫اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا القــرار‬\n\n\n‫‪55‬‬\n\f‫رقــم (‪ )3455890‬يف ‪1434/3/4‬ه ـ ونــص احلاجــة منــه ( وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة لوحــظ مــا يلــي أوال‪ :‬لــم يذكــر‬\n‫فضيلــة ناظــر القضيــة رقــم وتاريــخ األمــر الــذي أســتند عليــه املدعــي‬\n‫العــام مــن مرجعــه يف إقامــة الدعــوى ثانيــا ‪ :‬مــا أشــير إليــه باحلكــم‬\n‫مــن عــدم االختصــاص يف نظــر هــذه القضيــة يف غيــر محلــه فــا ينطبــق‬\n‫علــى الفعــل الصــادر مــن املدعــى عليهمــا نظــام مكافحــة الرشــوة فعلــى‬\n‫فضيلتــه االســتعانة بــاهلل وإكمــال نظــر القضيــة واهلل املوفــق ) وجوابــا‬\n‫علــى مــا ذكــره أصحــاب الفضيلــة يف أوال‪ :‬فــإن املدعــي العــام ‪..........‬‬\n‫مكلــف مــن هيئــة التحقيــق واالدعــاء العــام مبوجــب اخلطــاب رقــم ه ـ‬\n‫ن‪ 2128/1/2‬يف ‪1433/8/28‬ه ـ وأمــا املالحظــة ثانيــا فجوابـ ًا علــى مــا‬\n‫ذكــره أصحــاب الفضيلــة فــإن هــذه الدعــوى وأمثالهــا مــن اختصــاص‬\n‫القضــاء اإلداري (ديــوان املظالــم) لكونهــا تهديــد موظــف عــام وأرفــق‬\n‫بــن يــدي فضيلتكــم قــرار جلنــة تنــازع االختصــاص رقــم ‪/147‬ت يف‬\n‫‪1431/12/23‬ه ـ وهــذا اجتهــادي ومــا توصــل إليــه فهمــي واالجتهــاد‬\n‫ال ينقــض باالجتهــاد وعليــه فقــد قــررت رفــع اجللســة وإرســال املعاملــة‬\n‫حملكمــة االســتئناف للتمييــز علــى احلكــم حســب التعليمــات وصلــى‬\n                    ‫اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/3/29‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بشــرورة الشــيخ‪.............. /‬‬\n‫رقــم ‪ 341054909‬وتاريــخ ‪1434/5/13‬ه ـ املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلتــه رقــم ‪ 3428954‬وتاريــخ ‪1434/2/4‬ه ـ اخلــاص بدعــوى‬\n‫املدعــي العــام ضــد كل مــن ‪ ........ /‬و‪ (............‬ســعو ّديي اجلنســية )‬\n\n\n                                                                                     ‫‪56‬‬\n\f     ‫يف قضيــة ( تهديــد الغيــر ) علــى الصفــة املوضحــة يف القــرار املتضمــن‬\n     ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق دراســة القــرار‬\n     ‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n     ‫ـاء علــى قرارنــا رقــم ‪ 3455890‬وتاريــخ‬‫وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n     ‫‪1434/3/4‬ه ـ تقــررت املوافقــة علــى احلكــم بعد اإلجــراء األخير ‪ .‬واهلل‬\n                   ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪57‬‬\n\f‫تاريخه‪1434/3/28 :‬هـ‬‫ُ‬ ‫الص ِّك‪34173795 :‬‬   ‫َر ْق ُم َّ‬\n                     ‫عوى‪3432216 :‬‬   ‫الد َ‬  ‫َر ْق ُم َّ‬\n     ‫ِ‬\n    ‫االستئناف‪:‬‬ ‫صديق من محكم ِة‬\n                          ‫ِ‬    ‫َر ْق ُم قرا ِر ال َّت‬\n            ‫تاريخه‪1434/4/6 :‬هـ‬\n                            ‫ُ‬     ‫‪34179539‬‬\n\n\n‫اختصــاص ‪ -‬اســتر َداد ‪ُ -‬مطالب ـ ٌة باســتر َدا ِد حيــاز ِة منقــولٍ ‪ُ -‬مطالب ـ ٌة‬\n‫ـاص احملاكـ ِـم‬     ‫مبســتنداتٍ ‪ -‬اســتردا ُد احليــاز ِة يف املنقــولِ مِ ــن اخ ِتصـ ِ‬\n‫ـوابق‬\n  ‫ـاص ‪ -‬االســتنا ُد إلــى َسـ َ‬    ‫حتقـ ُـق التدافـ ِـع يف االخ ِتصـ ِ‬ ‫ُّ‬       ‫اجلزائي ـ ِة ‪-‬‬\n                     ‫الدع ـ َوى لعــد ِم االخ ِتصـ ِ‬\n    ‫ـاص ال َّنوعـ ِّـي‪.‬‬                          ‫ـرف ال َّنظ ـ ِر عـ ِـن َّ‬‫قضا